import type { BankQuestion } from "@/lib/bank";

/** Mensuration (Area and Volume) (Quantitative Aptitude): 209 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-mensuration-1","question":"The area of a rectangle 12 cm long and 8 cm wide is:","options":["40 cm²","80 cm²","96 cm²","192 cm²"],"answer":2,"explanation":"Area = length × breadth = 12 × 8 = 96 cm². 40 cm is the perimeter 2(12 + 8), a common mix-up, and 192 doubles the area.","difficulty":"easy","questionHi":"12 cm लंबे और 8 cm चौड़े आयत का क्षेत्रफल है:","optionsHi":["40 cm²","80 cm²","96 cm²","192 cm²"],"explanationHi":"क्षेत्रफल = लंबाई × चौड़ाई = 12 × 8 = 96 cm²। 40 cm परिमाप 2(12 + 8) है, जो एक आम भूल है, और 192 क्षेत्रफल का दोगुना है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-2","question":"The circumference of a circle of radius 7 cm is (π = 22/7):","options":["22 cm","44 cm","154 cm","88 cm"],"answer":1,"explanation":"Circumference = 2πr = 2 × 22/7 × 7 = 44 cm. 22 cm forgets the factor 2 (πr), and 154 cm² is the area πr², not the circumference.","difficulty":"easy","questionHi":"7 cm त्रिज्या वाले वृत्त की परिधि है (π = 22/7):","optionsHi":["22 cm","44 cm","154 cm","88 cm"],"explanationHi":"परिधि = 2πr = 2 × 22/7 × 7 = 44 cm। 22 cm में गुणनखंड 2 छूट गया है (πr), और 154 cm² क्षेत्रफल πr² है, परिधि नहीं।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-3","question":"The volume of a cube of side 5 cm is:","options":["25 cm³","100 cm³","125 cm³","150 cm³"],"answer":2,"explanation":"Volume = a³ = 5³ = 125 cm³. 25 is the area of one face (a²), and 150 is the total surface area 6a².","difficulty":"easy","questionHi":"5 cm भुजा वाले घन का आयतन है:","optionsHi":["25 cm³","100 cm³","125 cm³","150 cm³"],"explanationHi":"आयतन = a³ = 5³ = 125 cm³। 25 एक फलक का क्षेत्रफल (a²) है, और 150 कुल पृष्ठीय क्षेत्रफल 6a² है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-4","question":"The volume of a cylinder of radius 7 cm and height 10 cm is (π = 22/7):","options":["440 cm³","1,540 cm³","3,080 cm³","770 cm³"],"answer":1,"explanation":"Volume = πr²h = 22/7 × 49 × 10 = 1,540 cm³. 440 is the curved surface 2πrh, and 3,080 doubles the answer by using 2πr²h.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"7 cm त्रिज्या और 10 cm ऊँचाई वाले बेलन का आयतन है (π = 22/7):","optionsHi":["440 cm³","1,540 cm³","3,080 cm³","770 cm³"],"explanationHi":"आयतन = πr²h = 22/7 × 49 × 10 = 1,540 cm³। 440 वक्र पृष्ठीय क्षेत्रफल 2πrh है, और 3,080 में 2πr²h लेने से उत्तर दोगुना हो जाता है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-5","question":"The area of a circle is 154 cm². Its radius is (π = 22/7):","options":["7 cm","14 cm","11 cm","21 cm"],"answer":0,"explanation":"πr² = 154 gives r² = 154 × 7/22 = 49, so r = 7 cm. 14 cm is the diameter, and 11 or 21 come from mishandling the 22/7 when solving.","difficulty":"moderate","questionHi":"एक वृत्त का क्षेत्रफल 154 cm² है। उसकी त्रिज्या है (π = 22/7):","optionsHi":["7 cm","14 cm","11 cm","21 cm"],"explanationHi":"πr² = 154 से r² = 154 × 7/22 = 49, अतः r = 7 cm। 14 cm व्यास है, और 11 या 21 हल करते समय 22/7 को गलत संभालने से आते हैं।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-6","question":"The length of the diagonal of a cuboid measuring 12 cm × 4 cm × 3 cm is:","options":["11 cm","13 cm","15 cm","19 cm"],"answer":1,"explanation":"Diagonal = √(l² + b² + h²) = √(144 + 16 + 9) = √169 = 13 cm. 19 cm simply adds the three edges, and 11 or 15 are arithmetic slips under the root.","difficulty":"moderate","questionHi":"12 cm × 4 cm × 3 cm माप वाले घनाभ के विकर्ण की लंबाई है:","optionsHi":["11 cm","13 cm","15 cm","19 cm"],"explanationHi":"विकर्ण = √(l² + b² + h²) = √(144 + 16 + 9) = √169 = 13 cm। 19 cm में तीनों किनारों को सीधे जोड़ दिया गया है, और 11 या 15 मूल के अंदर की गणना की भूल से आते हैं।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-7","question":"The curved surface area of a cone of radius 7 cm and height 24 cm is (π = 22/7):","options":["528 cm²","550 cm²","704 cm²","1,232 cm²"],"answer":1,"explanation":"Slant height = √(49 + 576) = 25 cm; πrl = 22/7 × 7 × 25 = 550 cm².","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"7 cm त्रिज्या और 24 cm ऊँचाई वाले शंकु का वक्र पृष्ठीय क्षेत्रफल है (π = 22/7):","optionsHi":["528 cm²","550 cm²","704 cm²","1,232 cm²"],"explanationHi":"तिर्यक ऊँचाई = √(49 + 576) = 25 cm; πrl = 22/7 × 7 × 25 = 550 cm²।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-8","question":"The volume of a sphere of radius 21 cm is (π = 22/7):","options":["5,544 cm³","9,702 cm³","38,808 cm³","29,106 cm³"],"answer":2,"explanation":"V = ⁴⁄₃πr³ = ⁴⁄₃ × 22/7 × 9,261 = 38,808 cm³. 29,106 uses πr³ without the 4/3, and 5,544 is the surface area 4πr² (in cm²).","difficulty":"hard","questionHi":"21 cm त्रिज्या वाले गोले का आयतन है (π = 22/7):","optionsHi":["5,544 cm³","9,702 cm³","38,808 cm³","29,106 cm³"],"explanationHi":"V = ⁴⁄₃πr³ = ⁴⁄₃ × 22/7 × 9,261 = 38,808 cm³। 29,106 में 4/3 के बिना πr³ लिया गया है, और 5,544 पृष्ठीय क्षेत्रफल 4πr² है (cm² में)।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-9","question":"If the radius of a circle is increased by 10%, its area increases by:","options":["10%","20%","21%","11%"],"answer":2,"explanation":"Area ∝ r², so the factor is 1.1² = 1.21: a 21% rise. Using the formula a + b + ab/100 = 10 + 10 + 1 = 21; 20% forgets the ab/100 term and 10% treats area as linear in r.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"यदि किसी वृत्त की त्रिज्या में 10% की वृद्धि कर दी जाए, तो उसके क्षेत्रफल में वृद्धि होगी:","optionsHi":["10%","20%","21%","11%"],"explanationHi":"क्षेत्रफल ∝ r², अतः गुणक 1.1² = 1.21 है: यानी 21% की वृद्धि। सूत्र a + b + ab/100 = 10 + 10 + 1 = 21; 20% में ab/100 पद छूट गया है और 10% में क्षेत्रफल को r के रैखिक अनुपात में मान लिया गया है।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-10","question":"A cone and a cylinder have the same base radius and the same height. The ratio of the volume of the cylinder to that of the cone is:","options":["1 : 3","3 : 1","2 : 1","3 : 2"],"answer":1,"explanation":"A cone's volume is ⅓πr²h, so cylinder : cone = πr²h : ⅓πr²h = 3 : 1. 1 : 3 reverses the order asked, and 3 : 2 is the cylinder-to-sphere ratio (Archimedes).","difficulty":"very-hard","questionHi":"एक शंकु और एक बेलन की आधार त्रिज्या और ऊँचाई समान हैं। बेलन के आयतन और शंकु के आयतन का अनुपात है:","optionsHi":["1 : 3","3 : 1","2 : 1","3 : 2"],"explanationHi":"शंकु का आयतन ⅓πr²h होता है, अतः बेलन : शंकु = πr²h : ⅓πr²h = 3 : 1। 1 : 3 में पूछे गए क्रम को उलट दिया गया है, और 3 : 2 बेलन और गोले का अनुपात है (आर्किमिडीज़)।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-11","question":"A solid metal sphere of radius 6 cm is melted and recast into cones of radius 3 cm and height 4 cm. How many cones are made?","options":["12","18","24","36"],"answer":2,"explanation":"Sphere = ⁴⁄₃π × 216 = 288π; each cone = ⅓π × 9 × 4 = 12π; 288π ÷ 12π = 24.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"6 cm त्रिज्या वाले एक ठोस धातु के गोले को पिघलाकर 3 cm त्रिज्या और 4 cm ऊँचाई वाले शंकुओं में ढाला जाता है। कितने शंकु बनेंगे?","optionsHi":["12","18","24","36"],"explanationHi":"गोला = ⁴⁄₃π × 216 = 288π; प्रत्येक शंकु = ⅓π × 9 × 4 = 12π; 288π ÷ 12π = 24।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-12","question":"The total surface area of a solid hemisphere of radius 7 cm is (π = 22/7):","options":["308 cm²","462 cm²","616 cm²","924 cm²"],"answer":1,"explanation":"A solid hemisphere has a curved surface 2πr² plus a flat base πr², so TSA = 3πr² = 3 × 22/7 × 49 = 462 cm². 308 is only the curved surface, and 616 is the full sphere's 4πr².","difficulty":"very-hard","questionHi":"7 cm त्रिज्या वाले ठोस अर्धगोले का कुल पृष्ठीय क्षेत्रफल है (π = 22/7):","optionsHi":["308 cm²","462 cm²","616 cm²","924 cm²"],"explanationHi":"ठोस अर्धगोले का वक्र पृष्ठ 2πr² और समतल आधार πr² होता है, अतः कुल पृष्ठीय क्षेत्रफल = 3πr² = 3 × 22/7 × 49 = 462 cm²। 308 केवल वक्र पृष्ठ है, और 616 पूरे गोले का 4πr² है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-13","question":"A bucket is in the shape of a frustum of a cone with radii 14 cm and 7 cm and height 24 cm. Its capacity is (π = 22/7):","options":["8,624 cm³","8,232 cm³","9,856 cm³","7,392 cm³"],"answer":0,"explanation":"V = ⅓πh(R² + Rr + r²) = ⅓ × 22/7 × 24 × (196 + 98 + 49) = 22/7 × 8 × 343 = 22 × 8 × 49 = 8,624 cm³.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"एक बाल्टी शंकु के छिन्नक के आकार की है, जिसकी त्रिज्याएँ 14 cm और 7 cm तथा ऊँचाई 24 cm है। उसकी धारिता है (π = 22/7):","optionsHi":["8,624 cm³","8,232 cm³","9,856 cm³","7,392 cm³"],"explanationHi":"V = ⅓πh(R² + Rr + r²) = ⅓ × 22/7 × 24 × (196 + 98 + 49) = 22/7 × 8 × 343 = 22 × 8 × 49 = 8,624 cm³।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-14","question":"A toy is a cone mounted on a hemisphere of the same radius, 3.5 cm. The total height of the toy is 15.5 cm. Its total surface area is (π = 22/7):","options":["214.5 cm²","231 cm²","192.5 cm²","253 cm²"],"answer":0,"explanation":"Cone height = 15.5 − 3.5 = 12 cm, slant height = √(12² + 3.5²) = 12.5 cm. Area = πrl + 2πr² = πr(l + 2r) = 22/7 × 3.5 × (12.5 + 7) = 11 × 19.5 = 214.5 cm².","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक खिलौना 3.5 cm त्रिज्या वाले अर्धगोले पर उसी त्रिज्या के शंकु को रखकर बनाया गया है। खिलौने की कुल ऊँचाई 15.5 cm है। उसका कुल पृष्ठीय क्षेत्रफल है (π = 22/7):","optionsHi":["214.5 cm²","231 cm²","192.5 cm²","253 cm²"],"explanationHi":"शंकु की ऊँचाई = 15.5 − 3.5 = 12 cm, तिर्यक ऊँचाई = √(12² + 3.5²) = 12.5 cm। क्षेत्रफल = πrl + 2πr² = πr(l + 2r) = 22/7 × 3.5 × (12.5 + 7) = 11 × 19.5 = 214.5 cm²।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-15","question":"A solid sphere is cut into two equal hemispheres. By what percent does the total surface area increase?","options":["50%","25%","100%","75%"],"answer":0,"explanation":"Sphere: 4πr². Two hemispheres: 2 × 3πr² = 6πr², because each gains a flat circular face of πr². Increase = 2πr² ÷ 4πr² = 50%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"एक ठोस गोले को दो बराबर अर्धगोलों में काटा जाता है। कुल पृष्ठीय क्षेत्रफल में कितने प्रतिशत की वृद्धि होती है?","optionsHi":["50%","25%","100%","75%"],"explanationHi":"गोला: 4πr²। दो अर्धगोले: 2 × 3πr² = 6πr², क्योंकि प्रत्येक में πr² का एक समतल वृत्ताकार फलक जुड़ जाता है। वृद्धि = 2πr² ÷ 4πr² = 50%।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-16","question":"A cone is cut by a plane parallel to its base through the midpoint of its height. The ratio of the volume of the small cone to that of the frustum is:","options":["1 : 7","1 : 8","1 : 3","1 : 4"],"answer":0,"explanation":"The small cone is similar to the whole with linear ratio 1 : 2, so its volume is (1/2)³ = 1/8 of the whole. The frustum is the remaining 7/8, giving 1 : 7.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक शंकु को उसकी ऊँचाई के मध्य बिंदु से होकर आधार के समांतर तल से काटा जाता है। छोटे शंकु के आयतन और छिन्नक के आयतन का अनुपात है:","optionsHi":["1 : 7","1 : 8","1 : 3","1 : 4"],"explanationHi":"छोटा शंकु पूरे शंकु के समरूप है, जिसका रैखिक अनुपात 1 : 2 है, अतः उसका आयतन पूरे का (1/2)³ = 1/8 है। छिन्नक शेष 7/8 है, इसलिए अनुपात 1 : 7 होता है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-17","question":"The area of a rhombus whose diagonals are 16 cm and 12 cm is:","options":["192 cm²","96 cm²","48 cm²","56 cm²"],"answer":1,"explanation":"Area = ½ × d₁ × d₂ = ½ × 16 × 12 = 96 cm². 192 forgets the half.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"उस समचतुर्भुज का क्षेत्रफल, जिसके विकर्ण 16 cm और 12 cm हैं, है:","optionsHi":["192 cm²","96 cm²","48 cm²","56 cm²"],"explanationHi":"क्षेत्रफल = ½ × d₁ × d₂ = ½ × 16 × 12 = 96 cm²। 192 में आधा छूट गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-18","question":"The perimeter of a square whose area is 625 cm² is:","options":["125 cm","50 cm","100 cm","75 cm"],"answer":2,"explanation":"Side = √625 = 25 cm, so perimeter = 4 × 25 = 100 cm. 125 and 75 come from multiplying the side by 5 or 3 instead of 4, and 50 is twice the side.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"उस वर्ग का परिमाप, जिसका क्षेत्रफल 625 cm² है, है:","optionsHi":["125 cm","50 cm","100 cm","75 cm"],"explanationHi":"भुजा = √625 = 25 cm, अतः परिमाप = 4 × 25 = 100 cm। 125 और 75 भुजा को 4 के बजाय 5 या 3 से गुणा करने से आते हैं, और 50 भुजा का दोगुना है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-19","question":"The area of a triangle with sides 13 cm, 14 cm and 15 cm is:","options":["84 cm²","72 cm²","105 cm²","90 cm²"],"answer":0,"explanation":"Heron: s = 21, area = √(21 × 8 × 7 × 6) = √7,056 = 84 cm². Shortcut: the altitude to 14 is 12 (from 5-12-13 and 9-12-15), so area = ½ × 14 × 12 = 84. 105 uses ½ × 14 × 15.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"13 cm, 14 cm और 15 cm भुजाओं वाले त्रिभुज का क्षेत्रफल है:","optionsHi":["84 cm²","72 cm²","105 cm²","90 cm²"],"explanationHi":"हीरोन: s = 21, क्षेत्रफल = √(21 × 8 × 7 × 6) = √7,056 = 84 cm²। शॉर्टकट: 14 पर लंब 12 है (5-12-13 और 9-12-15 से), अतः क्षेत्रफल = ½ × 14 × 12 = 84। 105 में ½ × 14 × 15 लिया गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-20","question":"The area of an equilateral triangle of side 8 cm is:","options":["8√3 cm²","16√3 cm²","64√3 cm²","32√3 cm²"],"answer":1,"explanation":"Area = (√3/4)a² = (√3/4) × 64 = 16√3 cm². 64√3 forgets the 1/4, and 32√3 divides by 2 instead of 4.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"8 cm भुजा वाले समबाहु त्रिभुज का क्षेत्रफल है:","optionsHi":["8√3 cm²","16√3 cm²","64√3 cm²","32√3 cm²"],"explanationHi":"क्षेत्रफल = (√3/4)a² = (√3/4) × 64 = 16√3 cm²। 64√3 में 1/4 छूट गया है, और 32√3 में 4 के बजाय 2 से भाग दिया गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-21","question":"A circular field has an area of 616 m². The length of wire needed to fence it with 3 rounds is (π = 22/7):","options":["264 m","88 m","176 m","352 m"],"answer":0,"explanation":"πr² = 616 → r² = 196 → r = 14 m. Circumference = 2 × 22/7 × 14 = 88 m; three rounds = 264 m.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक वृत्ताकार खेत का क्षेत्रफल 616 m² है। उसे 3 फेरे तार से घेरने के लिए आवश्यक तार की लंबाई है (π = 22/7):","optionsHi":["264 m","88 m","176 m","352 m"],"explanationHi":"πr² = 616 → r² = 196 → r = 14 m। परिधि = 2 × 22/7 × 14 = 88 m; तीन फेरे = 264 m।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-22","question":"The base of a right prism is a triangle with sides 3 cm, 4 cm and 5 cm, and its height is 10 cm. Its volume is:","options":["30 cm³","50 cm³","120 cm³","60 cm³"],"answer":3,"explanation":"The base is a right triangle of area ½ × 3 × 4 = 6 cm². Volume = base area × height = 6 × 10 = 60 cm³.","difficulty":"moderate","source":"SSC CGL · CDS","questionHi":"एक समकोण प्रिज़्म का आधार 3 cm, 4 cm और 5 cm भुजाओं वाला त्रिभुज है और उसकी ऊँचाई 10 cm है। उसका आयतन है:","optionsHi":["30 cm³","50 cm³","120 cm³","60 cm³"],"explanationHi":"आधार एक समकोण त्रिभुज है जिसका क्षेत्रफल ½ × 3 × 4 = 6 cm² है। आयतन = आधार का क्षेत्रफल × ऊँचाई = 6 × 10 = 60 cm³।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-23","question":"The radius of the circle inscribed in a triangle with sides 6 cm, 8 cm and 10 cm is:","options":["5 cm","3 cm","4 cm","2 cm"],"answer":3,"explanation":"Right triangle (6² + 8² = 10²): area = 24, s = 12, inradius = area/s = 2 cm. (Also (6 + 8 − 10)/2 = 2.) 5 cm is the circumradius.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"6 cm, 8 cm और 10 cm भुजाओं वाले त्रिभुज के अंतःवृत्त की त्रिज्या है:","optionsHi":["5 cm","3 cm","4 cm","2 cm"],"explanationHi":"समकोण त्रिभुज (6² + 8² = 10²): क्षेत्रफल = 24, s = 12, अंतःत्रिज्या = क्षेत्रफल/s = 2 cm। (साथ ही (6 + 8 − 10)/2 = 2।) 5 cm परिवृत्त की त्रिज्या है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-24","question":"A solid metal sphere of radius 6 cm is dropped into a cylindrical vessel of radius 8 cm partly filled with water. The rise in the water level is:","options":["6 cm","4.5 cm","9 cm","3 cm"],"answer":1,"explanation":"Volume of sphere = 4/3 π × 216 = 288π cm³ = π × 8² × h, so h = 288/64 = 4.5 cm.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"6 cm त्रिज्या वाले एक ठोस धातु के गोले को 8 cm त्रिज्या वाले, आंशिक रूप से पानी से भरे बेलनाकार बर्तन में डाला जाता है। पानी के स्तर में वृद्धि है:","optionsHi":["6 cm","4.5 cm","9 cm","3 cm"],"explanationHi":"गोले का आयतन = 4/3 π × 216 = 288π cm³ = π × 8² × h, अतः h = 288/64 = 4.5 cm।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-25","question":"A frustum of a cone has end radii 10 cm and 4 cm and height 8 cm. Its slant height is:","options":["9 cm","10 cm","8 cm","12 cm"],"answer":1,"explanation":"Slant height = √(h² + (R − r)²) = √(64 + 36) = √100 = 10 cm.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक शंकु के छिन्नक के सिरों की त्रिज्याएँ 10 cm और 4 cm तथा ऊँचाई 8 cm है। उसकी तिर्यक ऊँचाई है:","optionsHi":["9 cm","10 cm","8 cm","12 cm"],"explanationHi":"तिर्यक ऊँचाई = √(h² + (R − r)²) = √(64 + 36) = √100 = 10 cm।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-26","question":"The radius of the circle circumscribing a right triangle with legs 5 cm and 12 cm is:","options":["2 cm","13 cm","6.5 cm","5 cm"],"answer":2,"explanation":"Hypotenuse = 13 cm, which is a diameter of the circumcircle, so the circumradius = 6.5 cm. 2 cm is the inradius.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"5 cm और 12 cm भुजाओं वाले समकोण त्रिभुज के परिवृत्त की त्रिज्या है:","optionsHi":["2 cm","13 cm","6.5 cm","5 cm"],"explanationHi":"कर्ण = 13 cm है, जो परिवृत्त का व्यास है, अतः परिवृत्त की त्रिज्या = 6.5 cm। 2 cm अंतःत्रिज्या है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-27","question":"A hemispherical bowl of internal radius 9 cm is full of liquid, which is poured into cylindrical bottles of radius 1.5 cm and height 4 cm. The number of bottles needed is:","options":["36","27","72","54"],"answer":3,"explanation":"Bowl = 2/3 π × 729 = 486π cm³; each bottle = π × 2.25 × 4 = 9π cm³. Bottles = 486/9 = 54.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"9 cm आंतरिक त्रिज्या वाला एक अर्धगोलाकार कटोरा द्रव से पूरा भरा है, जिसे 1.5 cm त्रिज्या और 4 cm ऊँचाई वाली बेलनाकार बोतलों में उँडेला जाता है। आवश्यक बोतलों की संख्या है:","optionsHi":["36","27","72","54"],"explanationHi":"कटोरा = 2/3 π × 729 = 486π cm³; प्रत्येक बोतल = π × 2.25 × 4 = 9π cm³। बोतलें = 486/9 = 54।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-28","question":"The diagonals of a rhombus are 24 cm and 10 cm. Its perimeter is:","options":["52 cm","60 cm","48 cm","26 cm"],"answer":0,"explanation":"Half-diagonals 12 and 5 form a right triangle with the side: side = √(144 + 25) = 13 cm. Perimeter = 52 cm.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक समचतुर्भुज के विकर्ण 24 cm और 10 cm हैं। उसका परिमाप है:","optionsHi":["52 cm","60 cm","48 cm","26 cm"],"explanationHi":"आधे विकर्ण 12 और 5 भुजा के साथ एक समकोण त्रिभुज बनाते हैं: भुजा = √(144 + 25) = 13 cm। परिमाप = 52 cm।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-29","question":"A circle is inscribed in an equilateral triangle of side 12√3 cm. The area of the circle is:","options":["36π cm²","12π cm²","108π cm²","144π cm²"],"answer":0,"explanation":"Inradius of an equilateral triangle = side/(2√3) = 12√3/(2√3) = 6 cm. Area = π × 36 = 36π cm². 144π uses the side as the radius.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"12√3 cm भुजा वाले समबाहु त्रिभुज में एक वृत्त अंतर्गत खींचा गया है। वृत्त का क्षेत्रफल है:","optionsHi":["36π cm²","12π cm²","108π cm²","144π cm²"],"explanationHi":"समबाहु त्रिभुज की अंतःत्रिज्या = भुजा/(2√3) = 12√3/(2√3) = 6 cm। क्षेत्रफल = π × 36 = 36π cm²। 144π में भुजा को ही त्रिज्या मान लिया गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-30","question":"A frustum of a cone has end radii 20 cm and 8 cm and height 9 cm. Its curved surface area is (π = 22/7):","options":["1,848 cm²","1,100 cm²","2,310 cm²","1,320 cm²"],"answer":3,"explanation":"Slant height = √(9² + 12²) = 15 cm. CSA = π(R + r)l = 22/7 × 28 × 15 = 1,320 cm².","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक शंकु के छिन्नक के सिरों की त्रिज्याएँ 20 cm और 8 cm तथा ऊँचाई 9 cm है। उसका वक्र पृष्ठीय क्षेत्रफल है (π = 22/7):","optionsHi":["1,848 cm²","1,100 cm²","2,310 cm²","1,320 cm²"],"explanationHi":"तिर्यक ऊँचाई = √(9² + 12²) = 15 cm। वक्र पृष्ठीय क्षेत्रफल = π(R + r)l = 22/7 × 28 × 15 = 1,320 cm²।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-31","question":"A solid cone of height 24 cm and base radius 6 cm is melted and recast into a solid sphere. The radius of the sphere is:","options":["12 cm","4 cm","6 cm","8 cm"],"answer":2,"explanation":"Cone volume = 1/3 π × 36 × 24 = 288π = 4/3 π r³ → r³ = 216 → r = 6 cm.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"24 cm ऊँचाई और 6 cm आधार त्रिज्या वाले एक ठोस शंकु को पिघलाकर ठोस गोले में ढाला जाता है। गोले की त्रिज्या है:","optionsHi":["12 cm","4 cm","6 cm","8 cm"],"explanationHi":"शंकु का आयतन = 1/3 π × 36 × 24 = 288π = 4/3 π r³ → r³ = 216 → r = 6 cm।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-32","question":"The area of the largest circle that can be drawn inside a square of area 196 cm² is (π = 22/7):","options":["308 cm²","616 cm²","196 cm²","154 cm²"],"answer":3,"explanation":"Side = 14 cm, so the circle's diameter is 14 cm and radius 7 cm. Area = 22/7 × 49 = 154 cm². 616 uses 14 cm as the radius.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"196 cm² क्षेत्रफल वाले वर्ग के अंदर खींचे जा सकने वाले सबसे बड़े वृत्त का क्षेत्रफल है (π = 22/7):","optionsHi":["308 cm²","616 cm²","196 cm²","154 cm²"],"explanationHi":"भुजा = 14 cm, अतः वृत्त का व्यास 14 cm और त्रिज्या 7 cm है। क्षेत्रफल = 22/7 × 49 = 154 cm²। 616 में 14 cm को त्रिज्या मान लिया गया है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-33","question":"A capsule-shaped solid consists of a cylinder of radius 3 cm and length 10 cm with a hemisphere of the same radius at each end. Its volume is:","options":["126π cm³","144π cm³","90π cm³","108π cm³"],"answer":0,"explanation":"Cylinder = π × 9 × 10 = 90π; the two hemispheres make a sphere of volume 4/3 π × 27 = 36π. Total 126π cm³.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"एक कैप्सूल के आकार का ठोस 3 cm त्रिज्या और 10 cm लंबाई वाले बेलन से बना है, जिसके प्रत्येक सिरे पर उसी त्रिज्या का एक अर्धगोला है। उसका आयतन है:","optionsHi":["126π cm³","144π cm³","90π cm³","108π cm³"],"explanationHi":"बेलन = π × 9 × 10 = 90π; दोनों अर्धगोले मिलकर एक गोला बनाते हैं जिसका आयतन 4/3 π × 27 = 36π है। कुल 126π cm³।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-34","question":"How many of the following statements are correct?\n1. The diagonal of a cube of side a is a√3.\n2. The volume of a cone is one-third that of a cylinder with the same base and height.\n3. The total surface area of a solid hemisphere of radius r is 2πr².\n4. Doubling the radius of a sphere multiplies its volume by 8.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"1, 2 and 4 are true (2³ = 8). 3 is false: the total surface area is 3πr² (curved 2πr² plus the flat face πr²). Three statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. a भुजा वाले घन का विकर्ण a√3 होता है।\n2. शंकु का आयतन उसी आधार और ऊँचाई वाले बेलन के आयतन का एक-तिहाई होता है।\n3. r त्रिज्या वाले ठोस अर्धगोले का कुल पृष्ठीय क्षेत्रफल 2πr² होता है।\n4. गोले की त्रिज्या दोगुनी करने पर उसका आयतन 8 गुना हो जाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"1, 2 और 4 सत्य हैं (2³ = 8)। 3 असत्य है: कुल पृष्ठीय क्षेत्रफल 3πr² है (वक्र पृष्ठ 2πr² और समतल फलक πr²)। तीन कथन सही हैं।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-35","question":"The base of a right prism is a right triangle with legs 6 cm and 8 cm, and the height of the prism is 10 cm. Its total surface area is:","options":["264 cm²","288 cm²","300 cm²","240 cm²"],"answer":1,"explanation":"Base area = 24 cm², base perimeter = 6 + 8 + 10 = 24 cm. TSA = 2 × 24 + 24 × 10 = 48 + 240 = 288 cm². 240 is the lateral area only.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक समकोण प्रिज़्म का आधार 6 cm और 8 cm भुजाओं वाला समकोण त्रिभुज है और प्रिज़्म की ऊँचाई 10 cm है। उसका कुल पृष्ठीय क्षेत्रफल है:","optionsHi":["264 cm²","288 cm²","300 cm²","240 cm²"],"explanationHi":"आधार का क्षेत्रफल = 24 cm², आधार का परिमाप = 6 + 8 + 10 = 24 cm। कुल पृष्ठीय क्षेत्रफल = 2 × 24 + 24 × 10 = 48 + 240 = 288 cm²। 240 केवल पार्श्व पृष्ठीय क्षेत्रफल है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-36","question":"A conical tent has base radius 7 m and height 24 m. The length of 2 m wide canvas needed to make it is (π = 22/7):","options":["300 m","250 m","275 m","550 m"],"answer":2,"explanation":"Slant height = √(49 + 576) = 25 m. CSA = 22/7 × 7 × 25 = 550 m². Canvas length = 550/2 = 275 m.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"एक शंक्वाकार तंबू की आधार त्रिज्या 7 m और ऊँचाई 24 m है। उसे बनाने के लिए 2 m चौड़े कैनवास की आवश्यक लंबाई है (π = 22/7):","optionsHi":["300 m","250 m","275 m","550 m"],"explanationHi":"तिर्यक ऊँचाई = √(49 + 576) = 25 m। वक्र पृष्ठीय क्षेत्रफल = 22/7 × 7 × 25 = 550 m²। कैनवास की लंबाई = 550/2 = 275 m।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-37","question":"What is the area of a triangle with base 14 cm and height 9 cm?","options":["126 cm²","63 cm²","23 cm²","56 cm²"],"answer":1,"explanation":"Area = ½ × base × height = ½ × 14 × 9 = 63 cm². 126 forgets the ½.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"आधार 14 cm और ऊँचाई 9 cm वाले त्रिभुज का क्षेत्रफल क्या है?","optionsHi":["126 cm²","63 cm²","23 cm²","56 cm²"],"explanationHi":"क्षेत्रफल = ½ × आधार × ऊँचाई = ½ × 14 × 9 = 63 cm²। 126 में ½ छूट गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-38","question":"What is the perimeter of a semicircle of radius 14 cm? (π = 22/7)","options":["72 cm","44 cm","88 cm","58 cm"],"answer":0,"explanation":"Perimeter = πr + 2r = 44 + 28 = 72 cm. 44 cm is only the curved arc, without the diameter.","difficulty":"moderate","source":"SSC CGL","questionHi":"14 cm त्रिज्या वाले अर्धवृत्त का परिमाप क्या है? (π = 22/7)","optionsHi":["72 cm","44 cm","88 cm","58 cm"],"explanationHi":"परिमाप = πr + 2r = 44 + 28 = 72 cm। 44 cm केवल वक्र चाप है, व्यास के बिना।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-39","question":"The volume of a cube is 343 cm³. What is its total surface area?","options":["196 cm²","245 cm²","343 cm²","294 cm²"],"answer":3,"explanation":"Side = ∛343 = 7 cm. TSA = 6a² = 6 × 49 = 294 cm². 196 cm² is the lateral area (4a²).","difficulty":"moderate","source":"SSC CGL","questionHi":"एक घन का आयतन 343 cm³ है। उसका कुल पृष्ठीय क्षेत्रफल क्या है?","optionsHi":["196 cm²","245 cm²","343 cm²","294 cm²"],"explanationHi":"भुजा = ∛343 = 7 cm। कुल पृष्ठीय क्षेत्रफल = 6a² = 6 × 49 = 294 cm²। 196 cm² पार्श्व पृष्ठीय क्षेत्रफल (4a²) है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-40","question":"A rectangular park is 40 m long and 30 m wide. A path 2 m wide runs all round it on the inside. What is the area of the path?","options":["280 m²","296 m²","264 m²","140 m²"],"answer":2,"explanation":"Inner rectangle = (40 − 4) × (30 − 4) = 36 × 26 = 936 m². Path = 1,200 − 936 = 264 m². 296 m² is a 2 m path outside the park.","difficulty":"hard","source":"SSC CGL","questionHi":"एक आयताकार पार्क 40 m लंबा और 30 m चौड़ा है। उसके अंदर चारों ओर 2 m चौड़ा एक रास्ता बना है। रास्ते का क्षेत्रफल क्या है?","optionsHi":["280 m²","296 m²","264 m²","140 m²"],"explanationHi":"भीतरी आयत = (40 − 4) × (30 − 4) = 36 × 26 = 936 m²। रास्ता = 1,200 − 936 = 264 m²। 296 m² पार्क के बाहर 2 m चौड़े रास्ते का क्षेत्रफल है।","subtopic":"paths-fields"},
  {"id":"quant-mensuration-41","question":"The radii of two cylinders are in the ratio 2 : 3 and their heights in the ratio 5 : 3. What is the ratio of their volumes?","options":["10 : 9","20 : 27","4 : 5","10 : 27"],"answer":1,"explanation":"V ∝ r²h, so the ratio = (4 × 5) : (9 × 3) = 20 : 27. 10 : 9 forgets to square the radii.","difficulty":"hard","source":"SSC CGL","questionHi":"दो बेलनों की त्रिज्याओं का अनुपात 2 : 3 है और उनकी ऊँचाइयों का अनुपात 5 : 3 है। उनके आयतनों का अनुपात क्या है?","optionsHi":["10 : 9","20 : 27","4 : 5","10 : 27"],"explanationHi":"V ∝ r²h, अतः अनुपात = (4 × 5) : (9 × 3) = 20 : 27। 10 : 9 में त्रिज्याओं का वर्ग करना छूट गया है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-42","question":"A rectangular sheet 44 cm × 18 cm is rolled along its length to form a hollow cylinder of height 18 cm. What is the volume of the cylinder? (π = 22/7)","options":["2,772 cm³","5,544 cm³","1,386 cm³","2,464 cm³"],"answer":0,"explanation":"The 44 cm length becomes the circumference: 2πr = 44 → r = 7 cm. Volume = πr²h = 154 × 18 = 2,772 cm³.","difficulty":"hard","source":"SSC CGL","questionHi":"44 cm × 18 cm की एक आयताकार चादर को उसकी लंबाई की दिशा में लपेटकर 18 cm ऊँचाई वाला खोखला बेलन बनाया जाता है। बेलन का आयतन क्या है? (π = 22/7)","optionsHi":["2,772 cm³","5,544 cm³","1,386 cm³","2,464 cm³"],"explanationHi":"44 cm की लंबाई परिधि बन जाती है: 2πr = 44 → r = 7 cm। आयतन = πr²h = 154 × 18 = 2,772 cm³।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-43","question":"Water flows at 5 m/s through a pipe of internal diameter 14 cm into a cylindrical tank of radius 3.5 m. By how much does the water level rise in 10 minutes?","options":["4.8 m","2.4 m","12 m","1.2 m"],"answer":3,"explanation":"Volume in 10 min = π(7)² × 500 cm/s × 600 s = π × 14,700,000 cm³. Tank base = π(350)² = π × 1,22,500 cm². Rise = 14,700,000 ÷ 1,22,500 = 120 cm = 1.2 m. 4.8 m uses 14 cm as the pipe's radius instead of its diameter.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"14 cm आंतरिक व्यास वाले पाइप से 5 m/s की चाल से पानी 3.5 m त्रिज्या वाली बेलनाकार टंकी में बहता है। 10 मिनट में पानी का स्तर कितना बढ़ेगा?","optionsHi":["4.8 m","2.4 m","12 m","1.2 m"],"explanationHi":"10 मिनट में आयतन = π(7)² × 500 cm/s × 600 s = π × 14,700,000 cm³। टंकी का आधार = π(350)² = π × 1,22,500 cm²। स्तर में वृद्धि = 14,700,000 ÷ 1,22,500 = 120 cm = 1.2 m। 4.8 m में पाइप के व्यास 14 cm को त्रिज्या मान लिया गया है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-44","question":"A solid is a cylinder of radius 3 cm and height 8 cm with a cone of the same radius and height 4 cm on top. It is melted and recast into spheres of radius 1 cm. How many spheres are made?","options":["54","72","63","84"],"answer":2,"explanation":"Volume = π(9)(8) + ⅓π(9)(4) = 72π + 12π = 84π. One sphere = (4/3)π. Number = 84π ÷ (4π/3) = 63. 84 forgets the sphere's 4/3 factor.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक ठोस 3 cm त्रिज्या और 8 cm ऊँचाई वाले बेलन के ऊपर उसी त्रिज्या और 4 cm ऊँचाई वाले शंकु को रखकर बना है। उसे पिघलाकर 1 cm त्रिज्या वाले गोलों में ढाला जाता है। कितने गोले बनेंगे?","optionsHi":["54","72","63","84"],"explanationHi":"आयतन = π(9)(8) + ⅓π(9)(4) = 72π + 12π = 84π। एक गोला = (4/3)π। संख्या = 84π ÷ (4π/3) = 63। 84 में गोले का 4/3 गुणक छूट गया है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-45","question":"The area of an equilateral triangle is 36√3 cm². What is the area of its circumcircle?","options":["36π cm²","48π cm²","12π cm²","144π cm²"],"answer":1,"explanation":"(√3/4)a² = 36√3 → a² = 144 → a = 12. Circumradius = a/√3 = 4√3, so area = π × 48 = 48π cm². 12π is the incircle (r = 2√3).","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक समबाहु त्रिभुज का क्षेत्रफल 36√3 cm² है। उसके परिवृत्त का क्षेत्रफल क्या है?","optionsHi":["36π cm²","48π cm²","12π cm²","144π cm²"],"explanationHi":"(√3/4)a² = 36√3 → a² = 144 → a = 12। परिवृत्त की त्रिज्या = a/√3 = 4√3, अतः क्षेत्रफल = π × 48 = 48π cm²। 12π अंतःवृत्त (r = 2√3) का क्षेत्रफल है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-46","question":"Earth dug out of a well of diameter 7 m and depth 20 m is spread evenly to form a platform 22 m long and 14 m wide. What is the height of the platform? (π = 22/7)","options":["2.5 m","10 m","1.25 m","3.5 m"],"answer":0,"explanation":"Earth = πr²h = 22/7 × 3.5² × 20 = 770 m³. Height = 770 ÷ (22 × 14) = 770 ÷ 308 = 2.5 m. 10 m takes the diameter 7 m as the radius.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"7 m व्यास और 20 m गहराई वाले कुएँ से निकाली गई मिट्टी को समान रूप से फैलाकर 22 m लंबा और 14 m चौड़ा एक चबूतरा बनाया जाता है। चबूतरे की ऊँचाई क्या है? (π = 22/7)","optionsHi":["2.5 m","10 m","1.25 m","3.5 m"],"explanationHi":"मिट्टी = πr²h = 22/7 × 3.5² × 20 = 770 m³। ऊँचाई = 770 ÷ (22 × 14) = 770 ÷ 308 = 2.5 m। 10 m में व्यास 7 m को त्रिज्या मान लिया गया है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-47","question":"What is the area of a trapezium whose parallel sides are 12 cm and 18 cm and whose height is 8 cm?","options":["120 cm²","144 cm²","108 cm²","240 cm²"],"answer":0,"explanation":"Area = (12 + 18)/2 × 8 = 15 × 8 = 120 cm². 240 cm² forgets to halve the sum.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"उस समलंब चतुर्भुज का क्षेत्रफल क्या है जिसकी समांतर भुजाएँ 12 cm और 18 cm हैं तथा ऊँचाई 8 cm है?","optionsHi":["120 cm²","144 cm²","108 cm²","240 cm²"],"explanationHi":"क्षेत्रफल = (12 + 18)/2 × 8 = 15 × 8 = 120 cm²। 240 cm² में योगफल को आधा करना छूट गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-48","question":"What is the area of a sector of a circle of radius 14 cm with a central angle of 90°? (π = 22/7)","options":["154 cm²","22 cm²","308 cm²","616 cm²"],"answer":0,"explanation":"A 90° sector is a quarter of the circle: ¼ × 22/7 × 14 × 14 = 154 cm². 616 is the whole circle and 308 is a semicircle.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"14 cm त्रिज्या वाले वृत्त के उस त्रिज्यखंड का क्षेत्रफल क्या है जिसका केंद्रीय कोण 90° है? (π = 22/7)","optionsHi":["154 cm²","22 cm²","308 cm²","616 cm²"],"explanationHi":"90° का त्रिज्यखंड वृत्त का एक-चौथाई होता है: ¼ × 22/7 × 14 × 14 = 154 cm²। 616 पूरे वृत्त का क्षेत्रफल है और 308 अर्धवृत्त का।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-49","question":"What is the lateral surface area of a cube of side 6 cm?","options":["36 cm²","144 cm²","96 cm²","216 cm²"],"answer":1,"explanation":"The lateral surface is the 4 side faces: 4 × 6² = 144 cm². 216 cm² is the total surface area (6 faces).","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"6 cm भुजा वाले घन का पार्श्व पृष्ठीय क्षेत्रफल क्या है?","optionsHi":["36 cm²","144 cm²","96 cm²","216 cm²"],"explanationHi":"पार्श्व पृष्ठ में 4 बगल के फलक होते हैं: 4 × 6² = 144 cm²। 216 cm² कुल पृष्ठीय क्षेत्रफल (6 फलक) है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-50","question":"What is the area of a square whose diagonal is 16 cm?","options":["128 cm²","256 cm²","112 cm²","64 cm²"],"answer":0,"explanation":"Area of a square = d²/2 = 256/2 = 128 cm². 256 cm² squares the diagonal as if it were the side.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"उस वर्ग का क्षेत्रफल क्या है जिसका विकर्ण 16 cm है?","optionsHi":["128 cm²","256 cm²","112 cm²","64 cm²"],"explanationHi":"वर्ग का क्षेत्रफल = d²/2 = 256/2 = 128 cm²। 256 cm² में विकर्ण का वर्ग इस प्रकार लिया गया है मानो वही भुजा हो।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-51","question":"A hollow metal pipe is 14 cm long, with external radius 8 cm and internal radius 6 cm. What is the volume of metal in it? (π = 22/7)","options":["2,464 cm³","1,584 cm³","1,232 cm³","176 cm³"],"answer":2,"explanation":"Volume = π(R² − r²)h = 22/7 × (64 − 36) × 14 = 22/7 × 28 × 14 = 1,232 cm³. Using (R − r)² = 4 instead of R² − r² gives 176.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक खोखले धातु के पाइप की लंबाई 14 cm है, बाहरी त्रिज्या 8 cm और भीतरी त्रिज्या 6 cm है। उसमें धातु का आयतन क्या है? (π = 22/7)","optionsHi":["2,464 cm³","1,584 cm³","1,232 cm³","176 cm³"],"explanationHi":"आयतन = π(R² − r²)h = 22/7 × (64 − 36) × 14 = 22/7 × 28 × 14 = 1,232 cm³। R² − r² के बजाय (R − r)² = 4 लेने पर 176 आता है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-52","question":"What is the length of an arc of a circle of radius 21 cm that subtends an angle of 60° at the centre? (π = 22/7)","options":["231 cm","44 cm","11 cm","22 cm"],"answer":3,"explanation":"Arc = 60/360 × 2 × 22/7 × 21 = 1/6 × 132 = 22 cm. 231 cm² is the sector's area, not the arc length.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"21 cm त्रिज्या वाले वृत्त के उस चाप की लंबाई क्या है जो केंद्र पर 60° का कोण अंतरित करता है? (π = 22/7)","optionsHi":["231 cm","44 cm","11 cm","22 cm"],"explanationHi":"चाप = 60/360 × 2 × 22/7 × 21 = 1/6 × 132 = 22 cm। 231 cm² त्रिज्यखंड का क्षेत्रफल है, चाप की लंबाई नहीं।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-53","question":"A room is 10 m long, 8 m wide and 4 m high. What does it cost to paint its four walls at ₹25 per m²?","options":["₹3,600","₹1,800","₹8,000","₹5,600"],"answer":0,"explanation":"Area of four walls = 2(l + b)h = 2 × 18 × 4 = 144 m², so the cost is 144 × 25 = ₹3,600. ₹5,600 also paints the ceiling (80 m²).","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक कमरा 10 m लंबा, 8 m चौड़ा और 4 m ऊँचा है। ₹25 प्रति m² की दर से उसकी चारों दीवारों को पेंट कराने का खर्च क्या है?","optionsHi":["₹3,600","₹1,800","₹8,000","₹5,600"],"explanationHi":"चारों दीवारों का क्षेत्रफल = 2(l + b)h = 2 × 18 × 4 = 144 m², अतः खर्च = 144 × 25 = ₹3,600। ₹5,600 में छत (80 m²) की पुताई भी शामिल है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-54","question":"A wheel has a diameter of 70 cm. How many revolutions does it make in covering 1.1 km? (π = 22/7)","options":["250","500","550","1,000"],"answer":1,"explanation":"Circumference = 22/7 × 70 = 220 cm = 2.2 m, so revolutions = 1,100/2.2 = 500. Using the radius as the diameter gives 1,000.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक पहिये का व्यास 70 cm है। 1.1 km की दूरी तय करने में वह कितने चक्कर लगाएगा? (π = 22/7)","optionsHi":["250","500","550","1,000"],"explanationHi":"परिधि = 22/7 × 70 = 220 cm = 2.2 m, अतः चक्करों की संख्या = 1,100/2.2 = 500। त्रिज्या के स्थान पर व्यास लेने से 1,000 आता है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-55","question":"What is the volume of a cone of radius 6 cm and height 7 cm? (π = 22/7)","options":["132 cm³","308 cm³","792 cm³","264 cm³"],"answer":3,"explanation":"V = 1/3 × 22/7 × 36 × 7 = 264 cm³. 792 cm³ is the volume of the cylinder with the same base and height.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"6 cm त्रिज्या और 7 cm ऊँचाई वाले शंकु का आयतन क्या है? (π = 22/7)","optionsHi":["132 cm³","308 cm³","792 cm³","264 cm³"],"explanationHi":"V = 1/3 × 22/7 × 36 × 7 = 264 cm³। 792 cm³ उसी आधार और ऊँचाई वाले बेलन का आयतन है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-56","question":"The radius of a cylinder is decreased by 10% and its height is increased by 20%. What happens to its volume?","options":["It increases by 10%","It decreases by 2.8%","It increases by 8%","It decreases by 1%"],"answer":1,"explanation":"V ∝ r²h: 0.9² × 1.2 = 0.81 × 1.2 = 0.972, a 2.8% decrease. Treating r as a single factor (0.9 × 1.2 = 1.08) gives the wrong 8% increase.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक बेलन की त्रिज्या में 10% की कमी और ऊँचाई में 20% की वृद्धि की जाती है। उसके आयतन का क्या होगा?","optionsHi":["10% बढ़ जाएगा","2.8% घट जाएगा","8% बढ़ जाएगा","1% घट जाएगा"],"explanationHi":"V ∝ r²h: 0.9² × 1.2 = 0.81 × 1.2 = 0.972, यानी 2.8% की कमी। r को एक ही बार गुणक मानने (0.9 × 1.2 = 1.08) पर 8% वृद्धि का गलत उत्तर मिलता है।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-57","question":"A rectangular field 60 m long and 40 m wide has two roads, each 3 m wide, running through its middle, one parallel to the length and the other parallel to the breadth. What is the total area of the roads?","options":["300 m²","291 m²","309 m²","282 m²"],"answer":1,"explanation":"Area = 3 × 60 + 3 × 40 − 3 × 3 = 180 + 120 − 9 = 291 m². The 9 m² crossing is counted twice unless it is subtracted.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"60 m लंबे और 40 m चौड़े आयताकार खेत के बीच से दो सड़कें गुजरती हैं, प्रत्येक 3 m चौड़ी, एक लंबाई के समांतर और दूसरी चौड़ाई के समांतर। सड़कों का कुल क्षेत्रफल क्या है?","optionsHi":["300 m²","291 m²","309 m²","282 m²"],"explanationHi":"क्षेत्रफल = 3 × 60 + 3 × 40 − 3 × 3 = 180 + 120 − 9 = 291 m²। 9 m² का कटान वाला भाग दो बार गिना जाता है, जब तक उसे घटाया न जाए।","subtopic":"paths-fields"},
  {"id":"quant-mensuration-58","question":"The circumferences of two concentric circles are 88 cm and 132 cm. What is the area of the ring between them? (π = 22/7)","options":["770 cm²","1,386 cm²","154 cm²","616 cm²"],"answer":0,"explanation":"Radii: 88 = 2πr gives r = 14 cm, and 132 gives R = 21 cm. Ring area = 22/7 × (441 − 196) = 22/7 × 245 = 770 cm². Using (R − r)² gives 154.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"दो संकेंद्रीय वृत्तों की परिधियाँ 88 cm और 132 cm हैं। उनके बीच के छल्ले का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["770 cm²","1,386 cm²","154 cm²","616 cm²"],"explanationHi":"त्रिज्याएँ: 88 = 2πr से r = 14 cm, और 132 से R = 21 cm। छल्ले का क्षेत्रफल = 22/7 × (441 − 196) = 22/7 × 245 = 770 cm²। (R − r)² लेने पर 154 आता है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-59","question":"A metal sphere of radius 3 cm is melted and drawn into a wire of radius 0.1 cm. How long is the wire?","options":["3.6 m","360 m","9 m","36 m"],"answer":3,"explanation":"4/3 π × 27 = π × 0.01 × L gives L = 36/0.01 = 3,600 cm = 36 m.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"3 cm त्रिज्या वाले एक धातु के गोले को पिघलाकर 0.1 cm त्रिज्या का तार खींचा जाता है। तार की लंबाई कितनी है?","optionsHi":["3.6 m","360 m","9 m","36 m"],"explanationHi":"4/3 π × 27 = π × 0.01 × L से L = 36/0.01 = 3,600 cm = 36 m।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-60","question":"How many bricks of size 25 cm × 12.5 cm × 7.5 cm are needed to build a wall 10 m long, 3 m high and 30 cm thick (ignoring mortar)?","options":["3,200","38,400","3,840","4,800"],"answer":2,"explanation":"Wall = 1,000 × 300 × 30 = 90,00,000 cm³; one brick = 25 × 12.5 × 7.5 = 2,343.75 cm³. Number = 90,00,000 ÷ 2,343.75 = 3,840.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"10 m लंबी, 3 m ऊँची और 30 cm मोटी दीवार बनाने के लिए 25 cm × 12.5 cm × 7.5 cm आकार की कितनी ईंटें चाहिए (गारे को छोड़कर)?","optionsHi":["3,200","38,400","3,840","4,800"],"explanationHi":"दीवार = 1,000 × 300 × 30 = 90,00,000 cm³; एक ईंट = 25 × 12.5 × 7.5 = 2,343.75 cm³। संख्या = 90,00,000 ÷ 2,343.75 = 3,840।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-61","question":"What is the area of a regular hexagon of side 6 cm?","options":["108√3 cm²","54√3 cm²","9√3 cm²","36√3 cm²"],"answer":1,"explanation":"A regular hexagon is 6 equilateral triangles: 6 × (√3/4) × 36 = 54√3 cm². 9√3 is just one triangle.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"6 cm भुजा वाले सम षट्भुज का क्षेत्रफल क्या है?","optionsHi":["108√3 cm²","54√3 cm²","9√3 cm²","36√3 cm²"],"explanationHi":"सम षट्भुज 6 समबाहु त्रिभुजों से बना होता है: 6 × (√3/4) × 36 = 54√3 cm²। 9√3 केवल एक त्रिभुज का क्षेत्रफल है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-62","question":"A square is inscribed in a circle. What is the ratio of the area of the circle to the area of the square? (π = 22/7)","options":["11 : 7","11 : 14","22 : 7","7 : 11"],"answer":0,"explanation":"If the radius is r, the square's diagonal is 2r, so its area is 2r². Ratio = πr² : 2r² = π/2 = 11 : 7. 22 : 7 uses the area r² for the square.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक वृत्त के अंदर एक वर्ग अंतर्गत खींचा गया है। वृत्त के क्षेत्रफल और वर्ग के क्षेत्रफल का अनुपात क्या है? (π = 22/7)","optionsHi":["11 : 7","11 : 14","22 : 7","7 : 11"],"explanationHi":"यदि त्रिज्या r है, तो वर्ग का विकर्ण 2r है, अतः उसका क्षेत्रफल 2r² है। अनुपात = πr² : 2r² = π/2 = 11 : 7। 22 : 7 में वर्ग का क्षेत्रफल r² ले लिया गया है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-63","question":"A sector of a circle of radius 21 cm with central angle 120° is folded into a cone (without overlap). What is the base radius of the cone?","options":["14 cm","21 cm","7 cm","10.5 cm"],"answer":2,"explanation":"The arc becomes the base circumference: 120/360 × 2π × 21 = 14π = 2πr, so r = 7 cm. The slant height is 21 cm.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"21 cm त्रिज्या और 120° केंद्रीय कोण वाले वृत्त के एक त्रिज्यखंड को मोड़कर (बिना ऊपर-नीचे चढ़ाए) एक शंकु बनाया जाता है। शंकु के आधार की त्रिज्या क्या है?","optionsHi":["14 cm","21 cm","7 cm","10.5 cm"],"explanationHi":"चाप आधार की परिधि बन जाता है: 120/360 × 2π × 21 = 14π = 2πr, अतः r = 7 cm। तिर्यक ऊँचाई 21 cm है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-64","question":"A cube of side 6 cm is cut into 8 equal smaller cubes. By how much does the total surface area increase?","options":["216 cm²","108 cm²","0 cm²","432 cm²"],"answer":0,"explanation":"The 8 cubes have side 3 cm, so total area = 8 × 6 × 9 = 432 cm², against 216 cm² before. The increase is 216 cm² (100%). 432 is the new total, not the increase.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"6 cm भुजा वाले एक घन को 8 बराबर छोटे घनों में काटा जाता है। कुल पृष्ठीय क्षेत्रफल में कितनी वृद्धि होती है?","optionsHi":["216 cm²","108 cm²","0 cm²","432 cm²"],"explanationHi":"8 घनों की भुजा 3 cm है, अतः कुल क्षेत्रफल = 8 × 6 × 9 = 432 cm², जबकि पहले 216 cm² था। वृद्धि 216 cm² (100%) है। 432 नया कुल क्षेत्रफल है, वृद्धि नहीं।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-65","question":"How many of the following statements are correct?\n1. The area of the circle inscribed in a square of side a is πa²/4.\n2. If the side of a cube is doubled, its volume becomes 8 times.\n3. The curved surface area of a hemisphere of radius r is 3πr².\n4. The slant height of a cone is √(r² + h²).","options":["All four","Only two","Only one","Only three"],"answer":3,"explanation":"1 (radius a/2), 2 (2³ = 8) and 4 (Pythagoras) are true. 3 is false: the curved surface of a hemisphere is 2πr²; 3πr² is its total surface area.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. a भुजा वाले वर्ग के अंदर बने अंतःवृत्त का क्षेत्रफल πa²/4 होता है।\n2. यदि घन की भुजा दोगुनी कर दी जाए, तो उसका आयतन 8 गुना हो जाता है।\n3. r त्रिज्या वाले अर्धगोले का वक्र पृष्ठीय क्षेत्रफल 3πr² होता है।\n4. शंकु की तिर्यक ऊँचाई √(r² + h²) होती है।","optionsHi":["सभी चार","केवल दो","केवल एक","केवल तीन"],"explanationHi":"1 (त्रिज्या a/2), 2 (2³ = 8) और 4 (पाइथागोरस) सत्य हैं। 3 असत्य है: अर्धगोले का वक्र पृष्ठीय क्षेत्रफल 2πr² होता है; 3πr² उसका कुल पृष्ठीय क्षेत्रफल है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-66","question":"A conical vessel of radius 6 cm and height 12 cm is full of water. The water is poured into a cylindrical vessel of radius 4 cm that already holds water to a height of 3 cm. What is the new height of the water in the cylinder?","options":["15 cm","6 cm","12 cm","9 cm"],"answer":2,"explanation":"Cone volume = 1/3 π × 36 × 12 = 144π cm³. In the cylinder it rises by 144π/(π × 16) = 9 cm, so the level becomes 3 + 9 = 12 cm. 9 cm forgets the water already there.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"6 cm त्रिज्या और 12 cm ऊँचाई वाला एक शंक्वाकार बर्तन पानी से भरा है। इस पानी को 4 cm त्रिज्या वाले उस बेलनाकार बर्तन में उँडेला जाता है जिसमें पहले से 3 cm ऊँचाई तक पानी भरा है। बेलन में पानी की नई ऊँचाई क्या है?","optionsHi":["15 cm","6 cm","12 cm","9 cm"],"explanationHi":"शंकु का आयतन = 1/3 π × 36 × 12 = 144π cm³। बेलन में यह 144π/(π × 16) = 9 cm ऊपर उठता है, अतः स्तर 3 + 9 = 12 cm हो जाता है। 9 cm में पहले से भरे पानी को भुला दिया गया है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-67","question":"From each corner of a square of side 14 cm, a quadrant of a circle of radius 7 cm is cut off. What is the area of the remaining part? (π = 22/7)","options":["98 cm²","42 cm²","154 cm²","49 cm²"],"answer":1,"explanation":"The four quadrants of radius 7 make one full circle of area 154 cm². Remaining = 196 − 154 = 42 cm².","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"14 cm भुजा वाले वर्ग के प्रत्येक कोने से 7 cm त्रिज्या वाला वृत्त का एक चतुर्थांश काट दिया जाता है। शेष भाग का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["98 cm²","42 cm²","154 cm²","49 cm²"],"explanationHi":"7 त्रिज्या वाले चारों चतुर्थांश मिलकर एक पूरा वृत्त बनाते हैं जिसका क्षेत्रफल 154 cm² है। शेष = 196 − 154 = 42 cm²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-68","question":"The areas of three adjacent faces of a cuboid are 24 cm², 32 cm² and 48 cm². What is its volume?","options":["96 cm³","192 cm³","36,864 cm³","104 cm³"],"answer":1,"explanation":"(lb)(bh)(hl) = (lbh)², so volume = √(24 × 32 × 48) = √36,864 = 192 cm³ (sides 4, 6, 8). 36,864 forgets the square root.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक घनाभ के तीन संलग्न फलकों के क्षेत्रफल 24 cm², 32 cm² और 48 cm² हैं। उसका आयतन क्या है?","optionsHi":["96 cm³","192 cm³","36,864 cm³","104 cm³"],"explanationHi":"(lb)(bh)(hl) = (lbh)², अतः आयतन = √(24 × 32 × 48) = √36,864 = 192 cm³ (भुजाएँ 4, 6, 8)। 36,864 में वर्गमूल लेना छूट गया है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-69","question":"A right triangle with legs 15 cm and 20 cm is rotated about its hypotenuse. What is the volume of the double cone formed?","options":["2,000π cm³","960π cm³","1,500π cm³","1,200π cm³"],"answer":3,"explanation":"Hypotenuse = 25 cm and the altitude to it = 15 × 20/25 = 12 cm, which is the common radius. The two cones' heights add to 25, so V = 1/3 π × 144 × 25 = 1,200π cm³. 1,500π and 2,000π come from rotating about a leg.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"15 cm और 20 cm भुजाओं वाले समकोण त्रिभुज को उसके कर्ण के परितः घुमाया जाता है। इससे बनने वाले दोहरे शंकु का आयतन क्या है?","optionsHi":["2,000π cm³","960π cm³","1,500π cm³","1,200π cm³"],"explanationHi":"कर्ण = 25 cm और उस पर डाला गया लंब = 15 × 20/25 = 12 cm है, जो दोनों शंकुओं की उभयनिष्ठ त्रिज्या है। दोनों शंकुओं की ऊँचाइयों का योग 25 है, अतः V = 1/3 π × 144 × 25 = 1,200π cm³। 1,500π और 2,000π किसी एक भुजा के परितः घुमाने से आते हैं।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-70","question":"5 cm of rain falls on a 2-hectare field. All the water is collected in a tank 50 m long and 40 m wide. By how much does the water level in the tank rise?","options":["0.05 m","5 m","0.5 m","2.5 m"],"answer":2,"explanation":"2 hectares = 20,000 m², so the water = 20,000 × 0.05 = 1,000 m³. Rise = 1,000/(50 × 40) = 0.5 m. Forgetting that 1 hectare = 10,000 m² throws the answer off by a power of 10.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"2 हेक्टेयर के खेत पर 5 cm वर्षा होती है। सारा पानी 50 m लंबी और 40 m चौड़ी एक टंकी में इकट्ठा किया जाता है। टंकी में पानी का स्तर कितना बढ़ेगा?","optionsHi":["0.05 m","5 m","0.5 m","2.5 m"],"explanationHi":"2 हेक्टेयर = 20,000 m², अतः पानी = 20,000 × 0.05 = 1,000 m³। स्तर में वृद्धि = 1,000/(50 × 40) = 0.5 m। यह भूल जाने पर कि 1 हेक्टेयर = 10,000 m² है, उत्तर 10 की घात से गलत हो जाता है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-71","question":"Assertion (A): If the radius of a sphere is doubled, its volume becomes 8 times.\nReason (R): The volume of a sphere is proportional to the cube of its radius.","options":["Both A and R are true, but R is not the correct explanation of A","A is false but R is true","A is true but R is false","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"V = 4/3 πr³, so doubling r multiplies V by 2³ = 8. A follows directly from R.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): यदि गोले की त्रिज्या दोगुनी कर दी जाए, तो उसका आयतन 8 गुना हो जाता है।\nकारण (R): गोले का आयतन उसकी त्रिज्या के घन के समानुपाती होता है।","optionsHi":["A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A असत्य है लेकिन R सत्य है","A सत्य है लेकिन R असत्य है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है"],"explanationHi":"V = 4/3 πr³, अतः r को दोगुना करने पर V, 2³ = 8 गुना हो जाता है। A सीधे R से निकलता है।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-72","question":"A hollow sphere has external radius 6 cm and internal radius 4 cm. It is melted and recast into a solid cone of base radius 8 cm. What is the height of the cone?","options":["10.5 cm","12 cm","9.5 cm","8 cm"],"answer":2,"explanation":"Metal = 4/3 π(216 − 64) = 4/3 π × 152. Cone: 1/3 π × 64 × h = 4/3 π × 152, so 64h = 608 and h = 9.5 cm.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक खोखले गोले की बाहरी त्रिज्या 6 cm और भीतरी त्रिज्या 4 cm है। उसे पिघलाकर 8 cm आधार त्रिज्या वाले ठोस शंकु में ढाला जाता है। शंकु की ऊँचाई क्या है?","optionsHi":["10.5 cm","12 cm","9.5 cm","8 cm"],"explanationHi":"धातु = 4/3 π(216 − 64) = 4/3 π × 152। शंकु: 1/3 π × 64 × h = 4/3 π × 152, अतः 64h = 608 और h = 9.5 cm।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-73","question":"What is the volume of the largest sphere that can be carved out of a cube of side 21 cm? (π = 22/7)","options":["4,158 cm³","4,851 cm³","38,808 cm³","9,261 cm³"],"answer":1,"explanation":"The sphere's diameter equals the side, so r = 10.5 cm and V = 4/3 × 22/7 × 10.5³ = 4,851 cm³. 38,808 uses r = 21 cm; 9,261 is the cube.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"21 cm भुजा वाले घन से तराशे जा सकने वाले सबसे बड़े गोले का आयतन क्या है? (π = 22/7)","optionsHi":["4,158 cm³","4,851 cm³","38,808 cm³","9,261 cm³"],"explanationHi":"गोले का व्यास घन की भुजा के बराबर है, अतः r = 10.5 cm और V = 4/3 × 22/7 × 10.5³ = 4,851 cm³। 38,808 में r = 21 cm लिया गया है; 9,261 घन का आयतन है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-74","question":"A circular park of radius 35 m has a 7 m wide path running round it on the outside. What is the cost of paving the path at ₹20 per m²? (π = 22/7)","options":["₹30,800","₹26,180","₹3,080","₹33,880"],"answer":3,"explanation":"Path area = 22/7 × (42² − 35²) = 22/7 × 539 = 1,694 m², so the cost = 1,694 × 20 = ₹33,880. Putting the path inside (35² − 28²) gives ₹26,180.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"35 m त्रिज्या वाले एक वृत्ताकार पार्क के बाहर चारों ओर 7 m चौड़ा रास्ता है। ₹20 प्रति m² की दर से रास्ते पर फर्श लगवाने का खर्च क्या है? (π = 22/7)","optionsHi":["₹30,800","₹26,180","₹3,080","₹33,880"],"explanationHi":"रास्ते का क्षेत्रफल = 22/7 × (42² − 35²) = 22/7 × 539 = 1,694 m², अतः खर्च = 1,694 × 20 = ₹33,880। रास्ते को अंदर की ओर मान लेने पर (35² − 28²) ₹26,180 आता है।","subtopic":"paths-fields"},
  {"id":"quant-mensuration-75","question":"A cylinder, a cone and a hemisphere have equal base radii, and the heights of the cylinder and the cone equal that radius. What is the ratio of their volumes?","options":["3 : 1 : 2","3 : 2 : 1","2 : 1 : 3","1 : 3 : 2"],"answer":0,"explanation":"With h = r: cylinder πr³, cone 1/3 πr³, hemisphere 2/3 πr³, i.e. 1 : 1/3 : 2/3 = 3 : 1 : 2.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"एक बेलन, एक शंकु और एक अर्धगोले की आधार त्रिज्याएँ बराबर हैं, और बेलन तथा शंकु की ऊँचाइयाँ उस त्रिज्या के बराबर हैं। उनके आयतनों का अनुपात क्या है?","optionsHi":["3 : 1 : 2","3 : 2 : 1","2 : 1 : 3","1 : 3 : 2"],"explanationHi":"h = r लेने पर: बेलन πr³, शंकु 1/3 πr³, अर्धगोला 2/3 πr³, अर्थात् 1 : 1/3 : 2/3 = 3 : 1 : 2।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-76","question":"The total area of the four walls of a room is 168 m². Its length is twice its breadth and its height is 4 m. What is the area of the floor?","options":["72 m²","84 m²","98 m²","128 m²"],"answer":2,"explanation":"2(l + b)h = 2 × 3b × 4 = 24b = 168, so b = 7 m and l = 14 m. Floor area = 14 × 7 = 98 m².","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक कमरे की चारों दीवारों का कुल क्षेत्रफल 168 m² है। उसकी लंबाई चौड़ाई की दोगुनी है और ऊँचाई 4 m है। फर्श का क्षेत्रफल क्या है?","optionsHi":["72 m²","84 m²","98 m²","128 m²"],"explanationHi":"2(l + b)h = 2 × 3b × 4 = 24b = 168, अतः b = 7 m और l = 14 m। फर्श का क्षेत्रफल = 14 × 7 = 98 m²।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-77","question":"A rectangle has a perimeter of 46 cm and a length of 15 cm. What is its area?","options":["225 cm²","120 cm²","690 cm²","115 cm²"],"answer":1,"explanation":"Length + breadth = 46/2 = 23, so breadth = 8 cm and area = 15 × 8 = 120 cm². 690 multiplies the perimeter by the length.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक आयत का परिमाप 46 cm और लंबाई 15 cm है। उसका क्षेत्रफल क्या है?","optionsHi":["225 cm²","120 cm²","690 cm²","115 cm²"],"explanationHi":"लंबाई + चौड़ाई = 46/2 = 23, अतः चौड़ाई = 8 cm और क्षेत्रफल = 15 × 8 = 120 cm²। 690 में परिमाप को लंबाई से गुणा कर दिया गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-78","question":"What is the area of a circle whose circumference is 88 cm? (π = 22/7)","options":["154 cm²","308 cm²","616 cm²","1,232 cm²"],"answer":2,"explanation":"2πr = 88 gives r = 14 cm, so area = 22/7 × 196 = 616 cm². 154 cm² takes r = 7 by dividing 88 by 4π instead of 2π, and 1,232 doubles the area.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"उस वृत्त का क्षेत्रफल क्या है जिसकी परिधि 88 cm है? (π = 22/7)","optionsHi":["154 cm²","308 cm²","616 cm²","1,232 cm²"],"explanationHi":"2πr = 88 से r = 14 cm, अतः क्षेत्रफल = 22/7 × 196 = 616 cm²। 154 cm² में 88 को 2π के बजाय 4π से भाग देकर r = 7 ले लिया गया है, और 1,232 क्षेत्रफल का दोगुना है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-79","question":"A water tank measures 2 m × 1.5 m × 1 m. How many litres of water can it hold?","options":["300","30,000","4,500","3,000"],"answer":3,"explanation":"Volume = 3 m³, and 1 m³ = 1,000 litres, so it holds 3,000 litres.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक पानी की टंकी का माप 2 m × 1.5 m × 1 m है। उसमें कितने लीटर पानी आ सकता है?","optionsHi":["300","30,000","4,500","3,000"],"explanationHi":"आयतन = 3 m³ और 1 m³ = 1,000 लीटर, अतः उसमें 3,000 लीटर पानी आता है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-80","question":"What is the area of a parallelogram with a base of 18 cm and a corresponding height of 7.5 cm?","options":["135 cm²","67.5 cm²","51 cm²","270 cm²"],"answer":0,"explanation":"Area = base × height = 18 × 7.5 = 135 cm². Halving (67.5) is the triangle formula.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"18 cm आधार और संगत ऊँचाई 7.5 cm वाले समांतर चतुर्भुज का क्षेत्रफल क्या है?","optionsHi":["135 cm²","67.5 cm²","51 cm²","270 cm²"],"explanationHi":"क्षेत्रफल = आधार × ऊँचाई = 18 × 7.5 = 135 cm²। आधा करने (67.5) पर त्रिभुज का सूत्र लग जाता है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-81","question":"The sides of a triangle are 9 cm, 12 cm and 15 cm. What is the length of the altitude drawn to the longest side?","options":["9 cm","7.2 cm","6 cm","8 cm"],"answer":1,"explanation":"9-12-15 is a right triangle, so its area is ½ × 9 × 12 = 54 cm². Altitude to 15 = 2 × 54/15 = 7.2 cm.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक त्रिभुज की भुजाएँ 9 cm, 12 cm और 15 cm हैं। सबसे लंबी भुजा पर डाले गए लंब की लंबाई क्या है?","optionsHi":["9 cm","7.2 cm","6 cm","8 cm"],"explanationHi":"9-12-15 एक समकोण त्रिभुज है, अतः उसका क्षेत्रफल ½ × 9 × 12 = 54 cm² है। 15 पर लंब = 2 × 54/15 = 7.2 cm।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-82","question":"A cylindrical drum has a radius of 35 cm and a height of 1 m. How many litres can it hold? (π = 22/7)","options":["3,850","38.5","385","192.5"],"answer":2,"explanation":"Volume = 22/7 × 35 × 35 × 100 = 3,85,000 cm³. 1 litre = 1,000 cm³, so 385 litres.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक बेलनाकार ड्रम की त्रिज्या 35 cm और ऊँचाई 1 m है। उसमें कितने लीटर आ सकता है? (π = 22/7)","optionsHi":["3,850","38.5","385","192.5"],"explanationHi":"आयतन = 22/7 × 35 × 35 × 100 = 3,85,000 cm³। 1 लीटर = 1,000 cm³, अतः 385 लीटर।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-83","question":"The volumes of two spheres are in the ratio 64 : 27. What is the ratio of their surface areas?","options":["4 : 3","64 : 27","8 : 3√3","16 : 9"],"answer":3,"explanation":"Volume ∝ r³, so the radii are in the ratio ∛64 : ∛27 = 4 : 3. Surface area ∝ r², giving 16 : 9.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"दो गोलों के आयतनों का अनुपात 64 : 27 है। उनके पृष्ठीय क्षेत्रफलों का अनुपात क्या है?","optionsHi":["4 : 3","64 : 27","8 : 3√3","16 : 9"],"explanationHi":"आयतन ∝ r³, अतः त्रिज्याओं का अनुपात ∛64 : ∛27 = 4 : 3 है। पृष्ठीय क्षेत्रफल ∝ r², जिससे 16 : 9 मिलता है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-84","question":"A wheel of radius 21 cm makes 500 revolutions. How far does it travel? (π = 22/7)","options":["0.66 km","6.6 km","0.33 km","1.32 km"],"answer":0,"explanation":"One revolution = 2 × 22/7 × 21 = 132 cm. 500 × 132 = 66,000 cm = 0.66 km. 0.33 km uses the radius instead of the diameter.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"21 cm त्रिज्या वाला एक पहिया 500 चक्कर लगाता है। वह कितनी दूरी तय करता है? (π = 22/7)","optionsHi":["0.66 km","6.6 km","0.33 km","1.32 km"],"explanationHi":"एक चक्कर = 2 × 22/7 × 21 = 132 cm। 500 × 132 = 66,000 cm = 0.66 km। 0.33 km में व्यास के बजाय त्रिज्या ली गई है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-85","question":"An equilateral triangle has a perimeter of 36 cm. What is its area?","options":["48√3 cm²","36√3 cm²","144 cm²","72√3 cm²"],"answer":1,"explanation":"Side = 36/3 = 12 cm, so area = (√3/4) × 144 = 36√3 cm². 144 cm² forgets the √3/4 factor, and 72√3 divides by 2 instead of 4.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक समबाहु त्रिभुज का परिमाप 36 cm है। उसका क्षेत्रफल क्या है?","optionsHi":["48√3 cm²","36√3 cm²","144 cm²","72√3 cm²"],"explanationHi":"भुजा = 36/3 = 12 cm, अतः क्षेत्रफल = (√3/4) × 144 = 36√3 cm²। 144 cm² में √3/4 गुणक छूट गया है, और 72√3 में 4 के बजाय 2 से भाग दिया गया है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-86","question":"The total surface area of a cube is 486 cm². What is its volume?","options":["512 cm³","243 cm³","729 cm³","1,000 cm³"],"answer":2,"explanation":"6a² = 486 gives a² = 81 and a = 9 cm, so volume = 9³ = 729 cm³. 243 is half the surface area, a common slip of dividing by 2 instead of 6.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक घन का कुल पृष्ठीय क्षेत्रफल 486 cm² है। उसका आयतन क्या है?","optionsHi":["512 cm³","243 cm³","729 cm³","1,000 cm³"],"explanationHi":"6a² = 486 से a² = 81 और a = 9 cm, अतः आयतन = 9³ = 729 cm³। 243 पृष्ठीय क्षेत्रफल का आधा है, जो 6 के बजाय 2 से भाग देने की आम भूल है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-87","question":"How many square tiles of side 60 cm are needed to pave a floor measuring 6 m × 4.2 m?","options":["7","700","84","70"],"answer":3,"explanation":"Convert to cm: (600 × 420)/(60 × 60) = 10 × 7 = 70 tiles. Counting along each side (10 by 7) is the quickest check.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"6 m × 4.2 m माप के फर्श पर बिछाने के लिए 60 cm भुजा वाली कितनी वर्गाकार टाइलें चाहिए?","optionsHi":["7","700","84","70"],"explanationHi":"cm में बदलने पर: (600 × 420)/(60 × 60) = 10 × 7 = 70 टाइलें। प्रत्येक भुजा के अनुदिश गिनना (10 गुणा 7) सबसे तेज़ जाँच है।","subtopic":"paths-fields"},
  {"id":"quant-mensuration-88","question":"A path 4 m wide runs along the inside of the boundary of a square park of side 50 m. What does it cost to pave the path at ₹20 per m²?","options":["₹14,720","₹17,280","₹16,000","₹15,360"],"answer":0,"explanation":"Path area = 50² − 42² = (50 − 42)(50 + 42) = 8 × 92 = 736 m², costing 736 × 20 = ₹14,720. ₹17,280 is for a path outside (58² − 50²).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"50 m भुजा वाले वर्गाकार पार्क की सीमा के भीतर की ओर 4 m चौड़ा रास्ता बना है। ₹20 प्रति m² की दर से रास्ते पर फर्श लगवाने का खर्च क्या है?","optionsHi":["₹14,720","₹17,280","₹16,000","₹15,360"],"explanationHi":"रास्ते का क्षेत्रफल = 50² − 42² = (50 − 42)(50 + 42) = 8 × 92 = 736 m², अतः खर्च 736 × 20 = ₹14,720। ₹17,280 बाहर की ओर बने रास्ते (58² − 50²) का है।","subtopic":"paths-fields"},
  {"id":"quant-mensuration-89","question":"The curved surface area of a cone is 550 cm² and its slant height is 25 cm. What is its volume? (π = 22/7)","options":["3,696 cm³","1,232 cm³","1,540 cm³","1,078 cm³"],"answer":1,"explanation":"πrl = 550 gives r = 550 × 7/(22 × 25) = 7 cm, so h = √(625 − 49) = 24 cm. Volume = ⅓ × 22/7 × 49 × 24 = 1,232 cm³. 3,696 forgets the ⅓.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक शंकु का वक्र पृष्ठीय क्षेत्रफल 550 cm² और तिर्यक ऊँचाई 25 cm है। उसका आयतन क्या है? (π = 22/7)","optionsHi":["3,696 cm³","1,232 cm³","1,540 cm³","1,078 cm³"],"explanationHi":"πrl = 550 से r = 550 × 7/(22 × 25) = 7 cm, अतः h = √(625 − 49) = 24 cm। आयतन = ⅓ × 22/7 × 49 × 24 = 1,232 cm³। 3,696 में ⅓ छूट गया है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-90","question":"A hemispherical bowl of internal diameter 42 cm is full of oil. The oil is poured into cylindrical bottles of radius 7 cm and height 6 cm. How many bottles are filled?","options":["42","14","21","18"],"answer":2,"explanation":"Bowl = ⅔ × π × 21³ and bottle = π × 7² × 6. Ratio = (⅔ × 9,261)/294 = 6,174/294 = 21. Using 42 as the radius is the usual slip.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"42 cm आंतरिक व्यास वाला एक अर्धगोलाकार कटोरा तेल से पूरा भरा है। तेल को 7 cm त्रिज्या और 6 cm ऊँचाई वाली बेलनाकार बोतलों में उँडेला जाता है। कितनी बोतलें भरती हैं?","optionsHi":["42","14","21","18"],"explanationHi":"कटोरा = ⅔ × π × 21³ और बोतल = π × 7² × 6। अनुपात = (⅔ × 9,261)/294 = 6,174/294 = 21। 42 को त्रिज्या मान लेना आम भूल है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-91","question":"What is the area of a triangle with sides 17 cm, 25 cm and 28 cm?","options":["240 cm²","420 cm²","196 cm²","210 cm²"],"answer":3,"explanation":"s = 35, so area = √(35 × 18 × 10 × 7) = √44,100 = 210 cm². 420 forgets that Heron's formula already includes the half.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"17 cm, 25 cm और 28 cm भुजाओं वाले त्रिभुज का क्षेत्रफल क्या है?","optionsHi":["240 cm²","420 cm²","196 cm²","210 cm²"],"explanationHi":"s = 35, अतः क्षेत्रफल = √(35 × 18 × 10 × 7) = √44,100 = 210 cm²। 420 में यह भुला दिया गया है कि हीरोन के सूत्र में आधा पहले से शामिल है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-92","question":"What is the length of the longest rod that can be placed in a room 12 m long, 9 m wide and 8 m high?","options":["17 m","15 m","29 m","20 m"],"answer":0,"explanation":"Longest rod = space diagonal = √(12² + 9² + 8²) = √289 = 17 m. 15 m is only the floor diagonal.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"12 m लंबे, 9 m चौड़े और 8 m ऊँचे कमरे में रखी जा सकने वाली सबसे लंबी छड़ की लंबाई क्या है?","optionsHi":["17 m","15 m","29 m","20 m"],"explanationHi":"सबसे लंबी छड़ = अंतराल विकर्ण = √(12² + 9² + 8²) = √289 = 17 m। 15 m केवल फर्श का विकर्ण है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-93","question":"The length of a cuboid is increased by 20%, its breadth decreased by 10% and its height increased by 25%. What is the change in its volume?","options":["35% decrease","35% increase","15% increase","32% increase"],"answer":1,"explanation":"New volume factor = 1.2 × 0.9 × 1.25 = 1.35, a 35% increase. Simply adding 20 − 10 + 25 = 35 works here only by coincidence, so always multiply.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक घनाभ की लंबाई में 20% की वृद्धि, चौड़ाई में 10% की कमी और ऊँचाई में 25% की वृद्धि की जाती है। उसके आयतन में क्या परिवर्तन होता है?","optionsHi":["35% की कमी","35% की वृद्धि","15% की वृद्धि","32% की वृद्धि"],"explanationHi":"नए आयतन का गुणक = 1.2 × 0.9 × 1.25 = 1.35, यानी 35% की वृद्धि। 20 − 10 + 25 = 35 जोड़ना यहाँ केवल संयोग से सही बैठता है, इसलिए हमेशा गुणा करें।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-94","question":"The area of the ring between two concentric circles is 1,386 cm² and the outer radius is 35 cm. What is the inner radius? (π = 22/7)","options":["21 cm","14 cm","28 cm","24.5 cm"],"answer":2,"explanation":"π(R² − r²) = 1,386 gives R² − r² = 441, so r² = 1,225 − 441 = 784 and r = 28 cm. 21 cm is √441, the trap.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"दो संकेंद्रीय वृत्तों के बीच के छल्ले का क्षेत्रफल 1,386 cm² है और बाहरी त्रिज्या 35 cm है। भीतरी त्रिज्या क्या है? (π = 22/7)","optionsHi":["21 cm","14 cm","28 cm","24.5 cm"],"explanationHi":"π(R² − r²) = 1,386 से R² − r² = 441, अतः r² = 1,225 − 441 = 784 और r = 28 cm। 21 cm, √441 है, जो जाल वाला विकल्प है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-95","question":"A sector of a circle of radius 21 cm has a perimeter of 64 cm. What is its area?","options":["462 cm²","346.5 cm²","115.5 cm²","231 cm²"],"answer":3,"explanation":"Arc = 64 − 2 × 21 = 22 cm. Area of a sector = ½ × arc × radius = ½ × 22 × 21 = 231 cm².","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"21 cm त्रिज्या वाले वृत्त के एक त्रिज्यखंड का परिमाप 64 cm है। उसका क्षेत्रफल क्या है?","optionsHi":["462 cm²","346.5 cm²","115.5 cm²","231 cm²"],"explanationHi":"चाप = 64 − 2 × 21 = 22 cm। त्रिज्यखंड का क्षेत्रफल = ½ × चाप × त्रिज्या = ½ × 22 × 21 = 231 cm²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-96","question":"How many lead shots of diameter 0.6 cm can be made from a cuboid of lead measuring 9 cm × 11 cm × 12 cm? (π = 22/7)","options":["10,500","84,000","1,050","21,000"],"answer":0,"explanation":"Each shot = 4/3 × 22/7 × 0.027 = 0.792/7 cm³. Number = 1,188 × 7/0.792 = 10,500. 84,000 is 8 times too many: it halves the radius twice (r = 0.15 cm).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"9 cm × 11 cm × 12 cm माप के सीसे के घनाभ से 0.6 cm व्यास की कितनी सीसे की गोलियाँ बनाई जा सकती हैं? (π = 22/7)","optionsHi":["10,500","84,000","1,050","21,000"],"explanationHi":"प्रत्येक गोली = 4/3 × 22/7 × 0.027 = 0.792/7 cm³। संख्या = 1,188 × 7/0.792 = 10,500। 84,000 आठ गुना अधिक है: उसमें त्रिज्या को दो बार आधा कर दिया गया है (r = 0.15 cm)।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-97","question":"A trapezium has parallel sides 25 cm and 11 cm and non-parallel sides 13 cm and 15 cm. What is its area?","options":["252 cm²","216 cm²","168 cm²","432 cm²"],"answer":1,"explanation":"Cutting off a parallelogram leaves a triangle with sides 13, 14 (= 25 − 11) and 15, whose area is 84, so the height is 2 × 84/14 = 12 cm. Area = ½ × (25 + 11) × 12 = 216 cm².","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक समलंब चतुर्भुज की समांतर भुजाएँ 25 cm और 11 cm तथा असमांतर भुजाएँ 13 cm और 15 cm हैं। उसका क्षेत्रफल क्या है?","optionsHi":["252 cm²","216 cm²","168 cm²","432 cm²"],"explanationHi":"एक समांतर चतुर्भुज काट देने पर 13, 14 (= 25 − 11) और 15 भुजाओं वाला त्रिभुज बचता है, जिसका क्षेत्रफल 84 है, अतः ऊँचाई = 2 × 84/14 = 12 cm। क्षेत्रफल = ½ × (25 + 11) × 12 = 216 cm²।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-98","question":"A cylinder has a curved surface area of 1,320 cm² and a volume of 6,930 cm³. What is its diameter? (π = 22/7)","options":["10.5 cm","14 cm","21 cm","42 cm"],"answer":2,"explanation":"Volume/CSA = πr²h/(2πrh) = r/2, so r/2 = 6,930/1,320 = 5.25 and r = 10.5 cm. Diameter = 21 cm; 10.5 cm is the radius.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक बेलन का वक्र पृष्ठीय क्षेत्रफल 1,320 cm² और आयतन 6,930 cm³ है। उसका व्यास क्या है? (π = 22/7)","optionsHi":["10.5 cm","14 cm","21 cm","42 cm"],"explanationHi":"आयतन/वक्र पृष्ठीय क्षेत्रफल = πr²h/(2πrh) = r/2, अतः r/2 = 6,930/1,320 = 5.25 और r = 10.5 cm। व्यास = 21 cm; 10.5 cm त्रिज्या है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-99","question":"3 cm of rain falls on a flat roof measuring 22 m × 20 m, and all the water drains into a cylindrical tank of diameter 2 m. By how much does the water level in the tank rise? (π = 22/7)","options":["1.05 m","2.1 m","13.2 m","4.2 m"],"answer":3,"explanation":"Water = 22 × 20 × 0.03 = 13.2 m³. Tank base = 22/7 × 1² m², so rise = 13.2 × 7/22 = 4.2 m. 1.05 m uses 2 m as the radius.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"22 m × 20 m माप की एक समतल छत पर 3 cm वर्षा होती है, और सारा पानी 2 m व्यास वाली बेलनाकार टंकी में बह जाता है। टंकी में पानी का स्तर कितना बढ़ेगा? (π = 22/7)","optionsHi":["1.05 m","2.1 m","13.2 m","4.2 m"],"explanationHi":"पानी = 22 × 20 × 0.03 = 13.2 m³। टंकी का आधार = 22/7 × 1² m², अतः स्तर में वृद्धि = 13.2 × 7/22 = 4.2 m। 1.05 m में 2 m को त्रिज्या मान लिया गया है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-100","question":"A cone of base radius 6 cm and height 8 cm is cut by a plane parallel to its base, halfway up its height. What is the volume of the frustum (the lower part)?","options":["84π cm³","96π cm³","72π cm³","12π cm³"],"answer":0,"explanation":"Whole cone = ⅓π × 36 × 8 = 96π. The top cone is similar with scale ½, so its volume is 96π/8 = 12π. Frustum = 96π − 12π = 84π cm³.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"6 cm आधार त्रिज्या और 8 cm ऊँचाई वाले शंकु को उसकी ऊँचाई के आधे पर आधार के समांतर तल से काटा जाता है। छिन्नक (निचले भाग) का आयतन क्या है?","optionsHi":["84π cm³","96π cm³","72π cm³","12π cm³"],"explanationHi":"पूरा शंकु = ⅓π × 36 × 8 = 96π। ऊपर का शंकु ½ अनुपात में समरूप है, अतः उसका आयतन 96π/8 = 12π है। छिन्नक = 96π − 12π = 84π cm³।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-101","question":"A sphere fits exactly inside a closed cylinder of height 14 cm. What volume of the cylinder is not occupied by the sphere (correct to two decimals)? (π = 22/7)","options":["1,437.33 cm³","718.67 cm³","539 cm³","1,078 cm³"],"answer":1,"explanation":"r = 7 cm and h = 14 cm. The sphere is ⅔ of the cylinder (Archimedes), so the empty space is ⅓ × 22/7 × 49 × 14 = 2,156/3 = 718.67 cm³.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक गोला 14 cm ऊँचाई वाले बंद बेलन में ठीक-ठीक समा जाता है। बेलन का वह आयतन कितना है जो गोले से नहीं भरा है (दशमलव के दो स्थानों तक)? (π = 22/7)","optionsHi":["1,437.33 cm³","718.67 cm³","539 cm³","1,078 cm³"],"explanationHi":"r = 7 cm और h = 14 cm। गोला बेलन का ⅔ है (आर्किमिडीज़), अतः खाली स्थान = ⅓ × 22/7 × 49 × 14 = 2,156/3 = 718.67 cm³।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-102","question":"Circles of radius 7 cm are drawn with centres at the three vertices of an equilateral triangle of side 14 cm. What is the area of the triangle not covered by the circles? (π = 22/7)","options":["(49√3 − 154) cm²","(98√3 − 77) cm²","(49√3 − 77) cm²","(196√3 − 77) cm²"],"answer":2,"explanation":"Triangle = (√3/4) × 14² = 49√3. The three 60° sectors add up to 180°, i.e. half a circle: ½ × 22/7 × 49 = 77. Uncovered = (49√3 − 77) cm².","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"14 cm भुजा वाले समबाहु त्रिभुज के तीनों शीर्षों को केंद्र मानकर 7 cm त्रिज्या के वृत्त खींचे जाते हैं। त्रिभुज का वह क्षेत्रफल कितना है जो वृत्तों से ढका नहीं है? (π = 22/7)","optionsHi":["(49√3 − 154) cm²","(98√3 − 77) cm²","(49√3 − 77) cm²","(196√3 − 77) cm²"],"explanationHi":"त्रिभुज = (√3/4) × 14² = 49√3। तीनों 60° के त्रिज्यखंड मिलकर 180° यानी आधा वृत्त बनाते हैं: ½ × 22/7 × 49 = 77। बिना ढका भाग = (49√3 − 77) cm²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-103","question":"Water flows at 15 km/h through a pipe of radius 7 cm into a rectangular tank measuring 21 m × 11 m. How long will it take the water level in the tank to rise by 50 cm? (π = 22/7)","options":["45 minutes","1 hour","20 minutes","30 minutes"],"answer":3,"explanation":"Flow per hour = 22/7 × 0.07² × 15,000 = 231 m³. Needed = 21 × 11 × 0.5 = 115.5 m³, which is half of 231, so 30 minutes. Keep every length in metres.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"7 cm त्रिज्या वाले पाइप से 15 km/h की चाल से पानी 21 m × 11 m माप की आयताकार टंकी में बहता है। टंकी में पानी का स्तर 50 cm बढ़ने में कितना समय लगेगा? (π = 22/7)","optionsHi":["45 मिनट","1 घंटा","20 मिनट","30 मिनट"],"explanationHi":"प्रति घंटे प्रवाह = 22/7 × 0.07² × 15,000 = 231 m³। आवश्यक = 21 × 11 × 0.5 = 115.5 m³, जो 231 का आधा है, अतः 30 मिनट। सभी लंबाइयाँ मीटर में रखें।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-104","question":"From a solid cylinder of radius 7 cm and height 24 cm, a cone of the same radius and height is hollowed out from one end. What is the total surface area of the remaining solid? (π = 22/7)","options":["1,760 cm²","1,914 cm²","1,606 cm²","1,210 cm²"],"answer":0,"explanation":"Remaining surface = cylinder's curved surface (1,056) + the one closed base (154) + the cone's curved surface inside (22/7 × 7 × 25 = 550) = 1,760 cm². 1,914 wrongly keeps both bases.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"7 cm त्रिज्या और 24 cm ऊँचाई वाले ठोस बेलन के एक सिरे से उसी त्रिज्या और ऊँचाई वाला शंकु खोखला काटकर निकाल लिया जाता है। शेष ठोस का कुल पृष्ठीय क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["1,760 cm²","1,914 cm²","1,606 cm²","1,210 cm²"],"explanationHi":"शेष पृष्ठ = बेलन का वक्र पृष्ठ (1,056) + एक बंद आधार (154) + अंदर शंकु का वक्र पृष्ठ (22/7 × 7 × 25 = 550) = 1,760 cm²। 1,914 में गलती से दोनों आधार गिन लिए गए हैं।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-105","question":"A rhombus has a perimeter of 100 cm, and one diagonal is 34 cm longer than the other. What is its area?","options":["672 cm²","336 cm²","600 cm²","384 cm²"],"answer":1,"explanation":"Side = 25 cm, and the half-diagonals x and x + 17 satisfy x² + (x + 17)² = 625, giving x = 7. Diagonals are 14 and 48 cm, area = ½ × 14 × 48 = 336 cm².","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक समचतुर्भुज का परिमाप 100 cm है और उसका एक विकर्ण दूसरे से 34 cm लंबा है। उसका क्षेत्रफल क्या है?","optionsHi":["672 cm²","336 cm²","600 cm²","384 cm²"],"explanationHi":"भुजा = 25 cm, और आधे विकर्ण x तथा x + 17 से x² + (x + 17)² = 625 बनता है, जिससे x = 7 मिलता है। विकर्ण 14 और 48 cm हैं, क्षेत्रफल = ½ × 14 × 48 = 336 cm²।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-106","question":"A closed wooden box has external dimensions 22 cm × 16 cm × 12 cm and is made of wood 1 cm thick. What is the volume of wood used?","options":["1,144 cm³","2,800 cm³","1,424 cm³","1,600 cm³"],"answer":2,"explanation":"A closed box loses 2 cm from every dimension: internal = 20 × 14 × 10 = 2,800 cm³. Wood = 4,224 − 2,800 = 1,424 cm³. 1,144 treats it as an open box (height 11).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बंद लकड़ी के बक्से की बाहरी माप 22 cm × 16 cm × 12 cm है और वह 1 cm मोटी लकड़ी का बना है। प्रयुक्त लकड़ी का आयतन क्या है?","optionsHi":["1,144 cm³","2,800 cm³","1,424 cm³","1,600 cm³"],"explanationHi":"बंद बक्से में हर विमा से 2 cm घट जाता है: भीतरी = 20 × 14 × 10 = 2,800 cm³। लकड़ी = 4,224 − 2,800 = 1,424 cm³। 1,144 में इसे खुला बक्सा (ऊँचाई 11) मान लिया गया है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-107","question":"A regular hexagon is inscribed in a circle of area 616 cm². What is the area of the hexagon? (π = 22/7)","options":["196√3 cm²","147√3 cm²","588√3 cm²","294√3 cm²"],"answer":3,"explanation":"r² = 616 × 7/22 = 196, so r = 14 cm, which is also the hexagon's side. Area = 6 × (√3/4) × 14² = 294√3 cm².","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"616 cm² क्षेत्रफल वाले वृत्त में एक सम षट्भुज अंतर्गत खींचा गया है। षट्भुज का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["196√3 cm²","147√3 cm²","588√3 cm²","294√3 cm²"],"explanationHi":"r² = 616 × 7/22 = 196, अतः r = 14 cm, जो षट्भुज की भुजा भी है। क्षेत्रफल = 6 × (√3/4) × 14² = 294√3 cm²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-108","question":"A square is inscribed in a circle of radius 14 cm, and a circle is inscribed in that square. What is the area of the smaller circle? (π = 22/7)","options":["308 cm²","616 cm²","154 cm²","392 cm²"],"answer":0,"explanation":"The square's diagonal is 28 cm, so its side is 14√2 and the inner radius is 7√2. Area = 22/7 × 98 = 308 cm², exactly half the outer circle.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"14 cm त्रिज्या वाले वृत्त में एक वर्ग अंतर्गत खींचा गया है, और उस वर्ग के अंदर एक वृत्त अंतर्गत खींचा गया है। छोटे वृत्त का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["308 cm²","616 cm²","154 cm²","392 cm²"],"explanationHi":"वर्ग का विकर्ण 28 cm है, अतः उसकी भुजा 14√2 और भीतरी त्रिज्या 7√2 है। क्षेत्रफल = 22/7 × 98 = 308 cm², जो बाहरी वृत्त का ठीक आधा है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-109","question":"A square has the same perimeter as an equilateral triangle of area 48√3 cm². What is the area of the square?","options":["144 cm²","108 cm²","96 cm²","192 cm²"],"answer":1,"explanation":"(√3/4)a² = 48√3 gives a² = 192, a = 8√3 cm. Perimeter = 24√3, so the square's side is 6√3 and its area is 108 cm².","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक वर्ग का परिमाप उस समबाहु त्रिभुज के परिमाप के बराबर है जिसका क्षेत्रफल 48√3 cm² है। वर्ग का क्षेत्रफल क्या है?","optionsHi":["144 cm²","108 cm²","96 cm²","192 cm²"],"explanationHi":"(√3/4)a² = 48√3 से a² = 192, a = 8√3 cm। परिमाप = 24√3, अतः वर्ग की भुजा 6√3 है और उसका क्षेत्रफल 108 cm² है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-110","question":"A bucket in the shape of a frustum has top and bottom radii of 21 cm and 7 cm and a depth of 24 cm. How many litres of water can it hold? (π = 22/7)","options":["14.784","48.048","16.016","12.012"],"answer":2,"explanation":"V = πh/3 × (R² + r² + Rr) = 22/7 × 8 × 637 = 16,016 cm³ = 16.016 litres. 14.784 wrongly uses a cylinder of the mean radius 14 cm.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बाल्टी शंकु के छिन्नक के आकार की है, जिसके ऊपरी और निचले सिरों की त्रिज्याएँ 21 cm और 7 cm तथा गहराई 24 cm है। उसमें कितने लीटर पानी आ सकता है? (π = 22/7)","optionsHi":["14.784","48.048","16.016","12.012"],"explanationHi":"V = πh/3 × (R² + r² + Rr) = 22/7 × 8 × 637 = 16,016 cm³ = 16.016 लीटर। 14.784 में गलती से माध्य त्रिज्या 14 cm वाला बेलन ले लिया गया है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-111","question":"Two horses are tied with 14 m ropes at two opposite corners of a square field of side 28 m. What area of the field can neither horse graze? (π = 22/7)","options":["630 m²","168 m²","322 m²","476 m²"],"answer":3,"explanation":"Each horse grazes a quadrant of radius 14: ¼ × 22/7 × 196 = 154 m². The quadrants do not overlap (14 + 14 is less than the 28√2 diagonal), so ungrazed = 784 − 308 = 476 m².","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"28 m भुजा वाले वर्गाकार खेत के दो सम्मुख कोनों पर दो घोड़े 14 m लंबी रस्सियों से बँधे हैं। खेत का कितना क्षेत्रफल दोनों में से कोई भी घोड़ा नहीं चर सकता? (π = 22/7)","optionsHi":["630 m²","168 m²","322 m²","476 m²"],"explanationHi":"प्रत्येक घोड़ा 14 त्रिज्या का एक चतुर्थांश चरता है: ¼ × 22/7 × 196 = 154 m²। चतुर्थांश एक-दूसरे पर नहीं चढ़ते (14 + 14, विकर्ण 28√2 से कम है), अतः बिना चरा क्षेत्र = 784 − 308 = 476 m²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-112","question":"A right triangle has legs of 7 cm and 24 cm. What is its perimeter?","options":["56 cm","84 cm","31 cm","168 cm"],"answer":0,"explanation":"Hypotenuse = √(49 + 576) = 25 cm, so the perimeter is 7 + 24 + 25 = 56 cm. 84 cm² is its area, a different quantity.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक समकोण त्रिभुज की भुजाएँ 7 cm और 24 cm हैं। उसका परिमाप क्या है?","optionsHi":["56 cm","84 cm","31 cm","168 cm"],"explanationHi":"कर्ण = √(49 + 576) = 25 cm, अतः परिमाप = 7 + 24 + 25 = 56 cm। 84 cm² उसका क्षेत्रफल है, जो एक अलग राशि है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-113","question":"What is the volume of a solid hemisphere of radius 21 cm? (π = 22/7)","options":["38,808 cm³","19,404 cm³","9,702 cm³","2,772 cm³"],"answer":1,"explanation":"Volume = ⅔πr³ = ⅔ × 22/7 × 9,261 = 19,404 cm³. 38,808 is the whole sphere and 2,772 is the curved surface area.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"21 cm त्रिज्या वाले ठोस अर्धगोले का आयतन क्या है? (π = 22/7)","optionsHi":["38,808 cm³","19,404 cm³","9,702 cm³","2,772 cm³"],"explanationHi":"आयतन = ⅔πr³ = ⅔ × 22/7 × 9,261 = 19,404 cm³। 38,808 पूरे गोले का आयतन है और 2,772 वक्र पृष्ठीय क्षेत्रफल है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-114","question":"What is the length of the diagonal of a rectangle measuring 15 cm × 8 cm?","options":["23 cm","19 cm","17 cm","12 cm"],"answer":2,"explanation":"Diagonal = √(15² + 8²) = √289 = 17 cm (8-15-17 is a Pythagorean triple).","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"15 cm × 8 cm माप वाले आयत के विकर्ण की लंबाई क्या है?","optionsHi":["23 cm","19 cm","17 cm","12 cm"],"explanationHi":"विकर्ण = √(15² + 8²) = √289 = 17 cm (8-15-17 एक पाइथागोरस त्रिक है)।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-115","question":"A rectangular plot has an area of 360 m², and its length and breadth are in the ratio 5 : 2. What is its perimeter?","options":["72 m","42 m","96 m","84 m"],"answer":3,"explanation":"5x × 2x = 10x² = 360, so x = 6: length 30 m, breadth 12 m. Perimeter = 2 × 42 = 84 m.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक आयताकार भूखंड का क्षेत्रफल 360 m² है और उसकी लंबाई तथा चौड़ाई का अनुपात 5 : 2 है। उसका परिमाप क्या है?","optionsHi":["72 m","42 m","96 m","84 m"],"explanationHi":"5x × 2x = 10x² = 360, अतः x = 6: लंबाई 30 m, चौड़ाई 12 m। परिमाप = 2 × 42 = 84 m।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-116","question":"What does it cost to paint the curved surface of a cylindrical pillar of diameter 70 cm and height 4 m at ₹15 per m²? (π = 22/7)","options":["₹132","₹264","₹66","₹1,320"],"answer":0,"explanation":"CSA = 2πrh = 2 × 22/7 × 0.35 × 4 = 8.8 m², and 8.8 × 15 = ₹132. ₹264 uses the diameter as the radius.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"70 cm व्यास और 4 m ऊँचाई वाले बेलनाकार खंभे की वक्र सतह पर ₹15 प्रति m² की दर से पेंट कराने का खर्च क्या है? (π = 22/7)","optionsHi":["₹132","₹264","₹66","₹1,320"],"explanationHi":"वक्र पृष्ठीय क्षेत्रफल = 2πrh = 2 × 22/7 × 0.35 × 4 = 8.8 m², और 8.8 × 15 = ₹132। ₹264 में व्यास को त्रिज्या मान लिया गया है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-117","question":"Two cubes, each of edge 6 cm, are joined end to end to form a cuboid. What is the total surface area of the cuboid?","options":["432 cm²","360 cm²","288 cm²","216 cm²"],"answer":1,"explanation":"The cuboid is 12 × 6 × 6: 2(72 + 36 + 72) = 360 cm². 432 forgets that two faces are hidden at the joint.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"6 cm किनारे वाले दो घनों को सिरे से सिरा जोड़कर एक घनाभ बनाया जाता है। घनाभ का कुल पृष्ठीय क्षेत्रफल क्या है?","optionsHi":["432 cm²","360 cm²","288 cm²","216 cm²"],"explanationHi":"घनाभ 12 × 6 × 6 का है: 2(72 + 36 + 72) = 360 cm²। 432 में यह भुला दिया गया है कि जोड़ पर दो फलक छिप जाते हैं।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-118","question":"The area of a circle increases from 154 cm² to 616 cm². By what percentage does its circumference increase?","options":["300%","200%","100%","50%"],"answer":2,"explanation":"The area grows 4 times, so the radius (and circumference) grows √4 = 2 times: a 100% increase. 300% is the area's increase.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक वृत्त का क्षेत्रफल 154 cm² से बढ़कर 616 cm² हो जाता है। उसकी परिधि में कितने प्रतिशत की वृद्धि होती है?","optionsHi":["300%","200%","100%","50%"],"explanationHi":"क्षेत्रफल 4 गुना हो जाता है, अतः त्रिज्या (और परिधि) √4 = 2 गुना हो जाती है: यानी 100% की वृद्धि। 300% क्षेत्रफल की वृद्धि है।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-119","question":"A rhombus has an area of 120 cm² and one diagonal of 24 cm. What is the length of its side?","options":["12 cm","17 cm","10 cm","13 cm"],"answer":3,"explanation":"Other diagonal = 2 × 120/24 = 10 cm. The half-diagonals 12 and 5 give side = √(144 + 25) = 13 cm.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक समचतुर्भुज का क्षेत्रफल 120 cm² है और एक विकर्ण 24 cm का है। उसकी भुजा की लंबाई क्या है?","optionsHi":["12 cm","17 cm","10 cm","13 cm"],"explanationHi":"दूसरा विकर्ण = 2 × 120/24 = 10 cm। आधे विकर्ण 12 और 5 से भुजा = √(144 + 25) = 13 cm।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-120","question":"A cone has a volume of 1,848 cm³ and a base radius of 14 cm. What is its height? (π = 22/7)","options":["9 cm","3 cm","27 cm","6 cm"],"answer":0,"explanation":"⅓ × 22/7 × 196 × h = 1,848 gives (616/3)h = 1,848, so h = 9 cm. 3 cm forgets the ⅓.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक शंकु का आयतन 1,848 cm³ और आधार त्रिज्या 14 cm है। उसकी ऊँचाई क्या है? (π = 22/7)","optionsHi":["9 cm","3 cm","27 cm","6 cm"],"explanationHi":"⅓ × 22/7 × 196 × h = 1,848 से (616/3)h = 1,848, अतः h = 9 cm। 3 cm में ⅓ छूट गया है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-121","question":"The diagonal of a square field is 50 m. What is its area in hectares?","options":["1.25","0.125","0.25","0.0125"],"answer":1,"explanation":"Area of a square = d²/2 = 2,500/2 = 1,250 m². 1 hectare = 10,000 m², so 0.125 hectare.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक वर्गाकार खेत का विकर्ण 50 m है। उसका क्षेत्रफल हेक्टेयर में क्या है?","optionsHi":["1.25","0.125","0.25","0.0125"],"explanationHi":"वर्ग का क्षेत्रफल = d²/2 = 2,500/2 = 1,250 m²। 1 हेक्टेयर = 10,000 m², अतः 0.125 हेक्टेयर।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-122","question":"A square and a circle each have a perimeter of 88 cm. By how much does the area of the circle exceed that of the square? (π = 22/7)","options":["154 cm²","88 cm²","132 cm²","44 cm²"],"answer":2,"explanation":"Circle: r = 14, area 616 cm². Square: side 22, area 484 cm². Difference = 132 cm². For a fixed perimeter the circle always encloses more.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक वर्ग और एक वृत्त, दोनों का परिमाप 88 cm है। वृत्त का क्षेत्रफल वर्ग के क्षेत्रफल से कितना अधिक है? (π = 22/7)","optionsHi":["154 cm²","88 cm²","132 cm²","44 cm²"],"explanationHi":"वृत्त: r = 14, क्षेत्रफल 616 cm²। वर्ग: भुजा 22, क्षेत्रफल 484 cm²। अंतर = 132 cm²। निश्चित परिमाप के लिए वृत्त हमेशा अधिक क्षेत्रफल घेरता है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-123","question":"A room is 8 m long and 6 m wide. What does it cost to carpet the floor with carpet 75 cm wide at ₹40 per metre?","options":["₹1,920","₹3,200","₹1,440","₹2,560"],"answer":3,"explanation":"Length of carpet = area/width = 48/0.75 = 64 m, costing 64 × 40 = ₹2,560. ₹1,920 forgets to divide by the width (48 × 40).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक कमरा 8 m लंबा और 6 m चौड़ा है। 75 cm चौड़े कालीन से फर्श को ढकने का खर्च ₹40 प्रति मीटर की दर से क्या है?","optionsHi":["₹1,920","₹3,200","₹1,440","₹2,560"],"explanationHi":"कालीन की लंबाई = क्षेत्रफल/चौड़ाई = 48/0.75 = 64 m, अतः खर्च 64 × 40 = ₹2,560। ₹1,920 में चौड़ाई से भाग देना छूट गया है (48 × 40)।","subtopic":"paths-fields"},
  {"id":"quant-mensuration-124","question":"A solid cube of edge 8 cm is cut into cubes of edge 2 cm. What is the ratio of the total surface area of the small cubes to that of the original cube?","options":["4 : 1","8 : 1","2 : 1","16 : 1"],"answer":0,"explanation":"There are (8/2)³ = 64 small cubes with total area 64 × 24 = 1,536 cm², against 6 × 64 = 384 cm². Ratio 4 : 1, i.e. the scale factor 8/2.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"8 cm किनारे वाले एक ठोस घन को 2 cm किनारे वाले घनों में काटा जाता है। छोटे घनों के कुल पृष्ठीय क्षेत्रफल और मूल घन के पृष्ठीय क्षेत्रफल का अनुपात क्या है?","optionsHi":["4 : 1","8 : 1","2 : 1","16 : 1"],"explanationHi":"(8/2)³ = 64 छोटे घन बनते हैं जिनका कुल क्षेत्रफल 64 × 24 = 1,536 cm² है, जबकि मूल का 6 × 64 = 384 cm² है। अनुपात 4 : 1, यानी स्केल गुणक 8/2।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-125","question":"A circle is inscribed in a right triangle with legs 20 cm and 21 cm. What is the area of the circle (correct to two decimals)? (π = 22/7)","options":["154 cm²","113.14 cm²","201.14 cm²","78.57 cm²"],"answer":1,"explanation":"Hypotenuse = 29 cm. For a right triangle the inradius is (a + b − c)/2 = (20 + 21 − 29)/2 = 6 cm. Area = 22/7 × 36 = 113.14 cm².","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"20 cm और 21 cm भुजाओं वाले समकोण त्रिभुज में एक वृत्त अंतर्गत खींचा गया है। वृत्त का क्षेत्रफल क्या है (दशमलव के दो स्थानों तक)? (π = 22/7)","optionsHi":["154 cm²","113.14 cm²","201.14 cm²","78.57 cm²"],"explanationHi":"कर्ण = 29 cm। समकोण त्रिभुज की अंतःत्रिज्या (a + b − c)/2 = (20 + 21 − 29)/2 = 6 cm होती है। क्षेत्रफल = 22/7 × 36 = 113.14 cm²।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-126","question":"A wire bent into a circle of radius 28 cm is straightened and bent into a square. What is the area of the square? (π = 22/7)","options":["2,464 cm²","1,764 cm²","1,936 cm²","3,872 cm²"],"answer":2,"explanation":"Wire length = 2 × 22/7 × 28 = 176 cm, so the square's side is 44 cm and its area 1,936 cm². 2,464 cm² is the circle's area.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"28 cm त्रिज्या वाले वृत्त के आकार में मोड़े गए एक तार को सीधा करके वर्ग के आकार में मोड़ा जाता है। वर्ग का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["2,464 cm²","1,764 cm²","1,936 cm²","3,872 cm²"],"explanationHi":"तार की लंबाई = 2 × 22/7 × 28 = 176 cm, अतः वर्ग की भुजा 44 cm और क्षेत्रफल 1,936 cm² है। 2,464 cm² वृत्त का क्षेत्रफल है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-127","question":"An iron pipe 21 cm long has an external diameter of 25 cm and is 1 cm thick. If 1 cm³ of iron weighs 8 g, what does the pipe weigh? (π = 22/7)","options":["13.2 kg","6.336 kg","11.616 kg","12.672 kg"],"answer":3,"explanation":"Radii 12.5 and 11.5 cm: volume = 22/7 × (12.5² − 11.5²) × 21 = 22/7 × 24 × 21 = 1,584 cm³. Weight = 1,584 × 8 g = 12.672 kg.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक लोहे का पाइप 21 cm लंबा है, उसका बाहरी व्यास 25 cm है और वह 1 cm मोटा है। यदि 1 cm³ लोहे का भार 8 g है, तो पाइप का भार क्या है? (π = 22/7)","optionsHi":["13.2 kg","6.336 kg","11.616 kg","12.672 kg"],"explanationHi":"त्रिज्याएँ 12.5 और 11.5 cm: आयतन = 22/7 × (12.5² − 11.5²) × 21 = 22/7 × 24 × 21 = 1,584 cm³। भार = 1,584 × 8 g = 12.672 kg।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-128","question":"A rectangular field has a perimeter of 140 m and an area of 1,200 m². What is the length of its diagonal?","options":["50 m","60 m","40 m","70 m"],"answer":0,"explanation":"l + b = 70 and lb = 1,200, so l² + b² = 70² − 2 × 1,200 = 2,500 and the diagonal is 50 m (the field is 40 m × 30 m).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक आयताकार खेत का परिमाप 140 m और क्षेत्रफल 1,200 m² है। उसके विकर्ण की लंबाई क्या है?","optionsHi":["50 m","60 m","40 m","70 m"],"explanationHi":"l + b = 70 और lb = 1,200, अतः l² + b² = 70² − 2 × 1,200 = 2,500 और विकर्ण 50 m है (खेत 40 m × 30 m का है)।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-129","question":"Each edge of a cube is increased by 50%. By what percentage does its total surface area increase?","options":["150%","125%","50%","237.5%"],"answer":1,"explanation":"Area scales as the square of the edge: 1.5² = 2.25, a 125% increase. 237.5% is the increase in volume (1.5³ = 3.375).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक घन के प्रत्येक किनारे में 50% की वृद्धि की जाती है। उसके कुल पृष्ठीय क्षेत्रफल में कितने प्रतिशत की वृद्धि होती है?","optionsHi":["150%","125%","50%","237.5%"],"explanationHi":"क्षेत्रफल किनारे के वर्ग के अनुसार बदलता है: 1.5² = 2.25, यानी 125% की वृद्धि। 237.5% आयतन की वृद्धि है (1.5³ = 3.375)।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-130","question":"The base radius of a cone is halved and its height is doubled. What happens to its volume?","options":["It stays the same","It decreases by 25%","It decreases by 50%","It increases by 100%"],"answer":2,"explanation":"Volume ∝ r²h, so the factor is (½)² × 2 = ½: a 50% decrease. Treating r and h as equally weighted wrongly gives 'no change'.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक शंकु की आधार त्रिज्या आधी और ऊँचाई दोगुनी कर दी जाती है। उसके आयतन का क्या होगा?","optionsHi":["वही रहेगा","25% घट जाएगा","50% घट जाएगा","100% बढ़ जाएगा"],"explanationHi":"आयतन ∝ r²h, अतः गुणक (½)² × 2 = ½ है: यानी 50% की कमी। r और h को समान महत्व का मानने पर गलती से 'कोई परिवर्तन नहीं' आता है।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-131","question":"A metal sphere of radius 4.2 cm is melted and recast into a cylinder of radius 6 cm. What is the height of the cylinder?","options":["2.058 cm","8.232 cm","3.6 cm","2.744 cm"],"answer":3,"explanation":"⁴⁄₃π(4.2)³ = π(6)²h, so h = 4 × 74.088/(3 × 36) = 2.744 cm. 8.232 cm uses 4πr³, forgetting to divide by 3.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"4.2 cm त्रिज्या वाले एक धातु के गोले को पिघलाकर 6 cm त्रिज्या वाले बेलन में ढाला जाता है। बेलन की ऊँचाई क्या है?","optionsHi":["2.058 cm","8.232 cm","3.6 cm","2.744 cm"],"explanationHi":"⁴⁄₃π(4.2)³ = π(6)²h, अतः h = 4 × 74.088/(3 × 36) = 2.744 cm। 8.232 cm में 4πr³ लिया गया है, 3 से भाग देना छूट गया है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-132","question":"The circumradius of an equilateral triangle is 8 cm. What is the area of the triangle?","options":["48√3 cm²","64√3 cm²","16√3 cm²","96√3 cm²"],"answer":0,"explanation":"For an equilateral triangle R = a/√3, so a = 8√3 and a² = 192; area = (√3/4) × 192 = 48√3 cm². 16√3 takes the side as 8, and 64√3 takes it as 2R = 16.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक समबाहु त्रिभुज की परिवृत्त त्रिज्या 8 cm है। त्रिभुज का क्षेत्रफल क्या है?","optionsHi":["48√3 cm²","64√3 cm²","16√3 cm²","96√3 cm²"],"explanationHi":"समबाहु त्रिभुज में R = a/√3, अतः a = 8√3 और a² = 192; क्षेत्रफल = (√3/4) × 192 = 48√3 cm²। 16√3 में भुजा को 8 मान लिया गया है, और 64√3 में 2R = 16।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-133","question":"A sector with a central angle of 72° has an arc length of 17.6 cm. What is the area of the sector? (π = 22/7)","options":["246.4 cm²","123.2 cm²","61.6 cm²","154 cm²"],"answer":1,"explanation":"72° is 1/5 of the circle, so the circumference is 88 cm and r = 14 cm. Area = ½ × arc × r = ½ × 17.6 × 14 = 123.2 cm².","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"72° केंद्रीय कोण वाले एक त्रिज्यखंड के चाप की लंबाई 17.6 cm है। त्रिज्यखंड का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["246.4 cm²","123.2 cm²","61.6 cm²","154 cm²"],"explanationHi":"72° वृत्त का 1/5 है, अतः परिधि 88 cm और r = 14 cm है। क्षेत्रफल = ½ × चाप × r = ½ × 17.6 × 14 = 123.2 cm²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-134","question":"A solid cone of radius 6 cm and height 16 cm is completely immersed in water in a cylindrical vessel of radius 12 cm. By how much does the water level rise?","options":["4 cm","1/3 cm","4/3 cm","16/9 cm"],"answer":2,"explanation":"Displaced volume = ⅓π × 36 × 16 = 192π; rise = 192π/(π × 144) = 4/3 cm. 4 cm forgets the ⅓ in the cone's volume.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"6 cm त्रिज्या और 16 cm ऊँचाई वाले एक ठोस शंकु को 12 cm त्रिज्या वाले बेलनाकार बर्तन के पानी में पूरी तरह डुबोया जाता है। पानी का स्तर कितना बढ़ता है?","optionsHi":["4 cm","1/3 cm","4/3 cm","16/9 cm"],"explanationHi":"विस्थापित आयतन = ⅓π × 36 × 16 = 192π; स्तर में वृद्धि = 192π/(π × 144) = 4/3 cm। 4 cm में शंकु के आयतन का ⅓ छूट गया है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-135","question":"A tent is a cylinder of radius 14 m and height 3 m topped by a cone of the same radius with a slant height of 25 m. How much canvas is needed for the tent, the floor excluded? (π = 22/7)","options":["1,980 m²","1,100 m²","1,672 m²","1,364 m²"],"answer":3,"explanation":"Canvas = cylinder's curved surface + cone's curved surface = 2 × 22/7 × 14 × 3 + 22/7 × 14 × 25 = 264 + 1,100 = 1,364 m². 1,980 wrongly adds the 616 m² floor.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक तंबू 14 m त्रिज्या और 3 m ऊँचाई वाले बेलन के ऊपर उसी त्रिज्या के शंकु को रखकर बना है, जिसकी तिर्यक ऊँचाई 25 m है। फर्श को छोड़कर तंबू के लिए कितना कैनवास चाहिए? (π = 22/7)","optionsHi":["1,980 m²","1,100 m²","1,672 m²","1,364 m²"],"explanationHi":"कैनवास = बेलन का वक्र पृष्ठ + शंकु का वक्र पृष्ठ = 2 × 22/7 × 14 × 3 + 22/7 × 14 × 25 = 264 + 1,100 = 1,364 m²। 1,980 में गलती से 616 m² का फर्श जोड़ दिया गया है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-136","question":"A cylindrical container of radius 6 cm and height 15 cm is full of ice cream. It is filled into cones of radius 3 cm and height 12 cm, each topped with a hemisphere of ice cream. How many such cones can be filled?","options":["10","15","12","20"],"answer":0,"explanation":"Container = π × 36 × 15 = 540π. Each cone with its hemispherical top = π(⅓ × 9 × 12 + ⅔ × 27) = 54π. 540π/54π = 10. Forgetting the hemisphere gives 15.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"6 cm त्रिज्या और 15 cm ऊँचाई वाला एक बेलनाकार डिब्बा आइसक्रीम से पूरा भरा है। इसे 3 cm त्रिज्या और 12 cm ऊँचाई वाले शंकुओं में भरा जाता है, और प्रत्येक के ऊपर आइसक्रीम का एक अर्धगोला बनाया जाता है। ऐसे कितने शंकु भरे जा सकते हैं?","optionsHi":["10","15","12","20"],"explanationHi":"डिब्बा = π × 36 × 15 = 540π। अर्धगोलाकार शीर्ष सहित प्रत्येक शंकु = π(⅓ × 9 × 12 + ⅔ × 27) = 54π। 540π/54π = 10। अर्धगोले को छोड़ देने पर 15 आता है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-137","question":"What is the ratio of the total surface area of a cube to the surface area of the sphere inscribed in it? (π = 22/7)","options":["11 : 21","21 : 11","6 : 11","42 : 11"],"answer":1,"explanation":"With edge a, the sphere has radius a/2 and area πa². Ratio = 6a² : (22/7)a² = 42 : 22 = 21 : 11.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक घन के कुल पृष्ठीय क्षेत्रफल और उसके अंदर अंतर्गत गोले के पृष्ठीय क्षेत्रफल का अनुपात क्या है? (π = 22/7)","optionsHi":["11 : 21","21 : 11","6 : 11","42 : 11"],"explanationHi":"किनारा a लेने पर गोले की त्रिज्या a/2 और क्षेत्रफल πa² है। अनुपात = 6a² : (22/7)a² = 42 : 22 = 21 : 11।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-138","question":"A running track has two straight parts of 100 m each and two semicircular ends. The inner radius of each end is 35 m and the track is 7 m wide. What is the area of the track? (π = 22/7)","options":["2,794 m²","1,694 m²","3,094 m²","4,494 m²"],"answer":2,"explanation":"Straight parts: 2 × 100 × 7 = 1,400 m². The two semicircular rings make one full ring: 22/7 × (42² − 35²) = 22/7 × 539 = 1,694 m². Total = 3,094 m².","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक दौड़ पथ में 100 m के दो सीधे भाग और दो अर्धवृत्ताकार सिरे हैं। प्रत्येक सिरे की भीतरी त्रिज्या 35 m है और पथ 7 m चौड़ा है। पथ का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["2,794 m²","1,694 m²","3,094 m²","4,494 m²"],"explanationHi":"सीधे भाग: 2 × 100 × 7 = 1,400 m²। दोनों अर्धवृत्ताकार छल्ले मिलकर एक पूरा छल्ला बनाते हैं: 22/7 × (42² − 35²) = 22/7 × 539 = 1,694 m²। कुल = 3,094 m²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-139","question":"The sum of the length, breadth and height of a cuboid is 19 cm and the length of its diagonal is 11 cm. What is its total surface area?","options":["120 cm²","361 cm²","220 cm²","240 cm²"],"answer":3,"explanation":"(l + b + h)² = l² + b² + h² + 2(lb + bh + hl), so the TSA = 19² − 11² = 361 − 121 = 240 cm². 120 is half of it.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक घनाभ की लंबाई, चौड़ाई और ऊँचाई का योग 19 cm है और उसके विकर्ण की लंबाई 11 cm है। उसका कुल पृष्ठीय क्षेत्रफल क्या है?","optionsHi":["120 cm²","361 cm²","220 cm²","240 cm²"],"explanationHi":"(l + b + h)² = l² + b² + h² + 2(lb + bh + hl), अतः कुल पृष्ठीय क्षेत्रफल = 19² − 11² = 361 − 121 = 240 cm²। 120 उसका आधा है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-140","question":"A sphere and a cube have equal surface areas. What is the ratio of the volume of the sphere to that of the cube?","options":["√6 : √π","√π : √6","6 : π","3 : 2"],"answer":0,"explanation":"4πr² = 6a² gives a = r√(2π/3). Then (⁴⁄₃πr³)/a³ = (4π/3)/(2π/3)^(3/2) = √(6/π). The sphere has the larger volume, as expected for equal surface area.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक गोले और एक घन के पृष्ठीय क्षेत्रफल बराबर हैं। गोले के आयतन और घन के आयतन का अनुपात क्या है?","optionsHi":["√6 : √π","√π : √6","6 : π","3 : 2"],"explanationHi":"4πr² = 6a² से a = r√(2π/3)। तब (⁴⁄₃πr³)/a³ = (4π/3)/(2π/3)^(3/2) = √(6/π)। गोले का आयतन अधिक है, जैसा समान पृष्ठीय क्षेत्रफल के लिए अपेक्षित है।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-141","question":"The sides of a triangle are 13 cm, 14 cm and 15 cm. What is the radius of its circumcircle?","options":["4 cm","8.125 cm","7.5 cm","8 cm"],"answer":1,"explanation":"Area = 84 cm² (Heron, s = 21). R = abc/(4 × area) = 2,730/336 = 8.125 cm. 4 cm is the inradius (area/s).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक त्रिभुज की भुजाएँ 13 cm, 14 cm और 15 cm हैं। उसके परिवृत्त की त्रिज्या क्या है?","optionsHi":["4 cm","8.125 cm","7.5 cm","8 cm"],"explanationHi":"क्षेत्रफल = 84 cm² (हीरोन, s = 21)। R = abc/(4 × क्षेत्रफल) = 2,730/336 = 8.125 cm। 4 cm अंतःत्रिज्या (क्षेत्रफल/s) है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-142","question":"Copper wire of diameter 2 mm is wound evenly round a cylinder of length 18 cm and diameter 14 cm so that it covers the whole curved surface in a single layer. What length of wire is used? (π = 22/7)","options":["79.2 m","19.8 m","39.6 m","3.96 m"],"answer":2,"explanation":"Number of turns = 180 mm ÷ 2 mm = 90, and each turn is a circumference of 22/7 × 14 = 44 cm. Length = 90 × 44 = 3,960 cm = 39.6 m.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2 mm व्यास के तांबे के तार को 18 cm लंबाई और 14 cm व्यास वाले बेलन पर समान रूप से इस प्रकार लपेटा जाता है कि वह एक ही परत में पूरी वक्र सतह को ढक लेता है। प्रयुक्त तार की लंबाई क्या है? (π = 22/7)","optionsHi":["79.2 m","19.8 m","39.6 m","3.96 m"],"explanationHi":"फेरों की संख्या = 180 mm ÷ 2 mm = 90, और प्रत्येक फेरा एक परिधि 22/7 × 14 = 44 cm का है। लंबाई = 90 × 44 = 3,960 cm = 39.6 m।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-143","question":"In a square of side 14 cm, a semicircle is drawn inward on each side as diameter. The semicircles overlap to form a four-petal flower. What is the area of the flower? (π = 22/7)","options":["84 cm²","196 cm²","154 cm²","112 cm²"],"answer":3,"explanation":"The four semicircles total 2 × 154 = 308 cm² and cover the square (196 cm²) with the petals counted twice. Petals = 308 − 196 = 112 cm².","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"14 cm भुजा वाले वर्ग की प्रत्येक भुजा को व्यास मानकर अंदर की ओर एक अर्धवृत्त खींचा जाता है। अर्धवृत्त एक-दूसरे पर चढ़कर चार पंखुड़ियों वाला फूल बनाते हैं। फूल का क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["84 cm²","196 cm²","154 cm²","112 cm²"],"explanationHi":"चारों अर्धवृत्तों का कुल क्षेत्रफल 2 × 154 = 308 cm² है और वे वर्ग (196 cm²) को ढकते हैं, जिसमें पंखुड़ियाँ दो बार गिनी जाती हैं। पंखुड़ियाँ = 308 − 196 = 112 cm²।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-144","question":"A pyramid has a square base of side 10 cm and a slant height (of each triangular face) of 13 cm. What is its volume?","options":["400 cm³","433.33 cm³","1,200 cm³","520 cm³"],"answer":0,"explanation":"Vertical height = √(13² − 5²) = 12 cm (5 is half the base). Volume = ⅓ × 100 × 12 = 400 cm³. 433.33 wrongly uses the slant height.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक पिरामिड का आधार 10 cm भुजा वाला वर्ग है और (प्रत्येक त्रिकोणीय फलक की) तिर्यक ऊँचाई 13 cm है। उसका आयतन क्या है?","optionsHi":["400 cm³","433.33 cm³","1,200 cm³","520 cm³"],"explanationHi":"ऊर्ध्वाधर ऊँचाई = √(13² − 5²) = 12 cm (5 आधार का आधा है)। आयतन = ⅓ × 100 × 12 = 400 cm³। 433.33 में गलती से तिर्यक ऊँचाई ले ली गई है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-145","question":"A right triangle has a perimeter of 60 cm and a hypotenuse of 25 cm. What is its area?","options":["300 cm²","150 cm²","120 cm²","187.5 cm²"],"answer":1,"explanation":"a + b = 35 and a² + b² = 625, so 2ab = 1,225 − 625 = 600, ab = 300 and the area = ab/2 = 150 cm² (legs 15 and 20).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक समकोण त्रिभुज का परिमाप 60 cm और कर्ण 25 cm है। उसका क्षेत्रफल क्या है?","optionsHi":["300 cm²","150 cm²","120 cm²","187.5 cm²"],"explanationHi":"a + b = 35 और a² + b² = 625, अतः 2ab = 1,225 − 625 = 600, ab = 300 और क्षेत्रफल = ab/2 = 150 cm² (भुजाएँ 15 और 20)।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-146","question":"A cone of height 20 cm is cut by a plane parallel to its base so that the two parts have equal volumes. At what height above the base is the cut made?","options":["10 cm","20/∛2 cm","20(1 − 1/∛2) cm","20(1 − 1/√2) cm"],"answer":2,"explanation":"The top cone must have half the volume, so its height is 20 × ∛(1/2) = 20/∛2. The cut is 20 − 20/∛2 = 20(1 − 1/∛2) cm above the base; 20/∛2 is measured from the apex.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"20 cm ऊँचाई वाले एक शंकु को आधार के समांतर तल से इस प्रकार काटा जाता है कि दोनों भागों के आयतन बराबर हों। आधार से कितनी ऊँचाई पर काट लगाया गया है?","optionsHi":["10 cm","20/∛2 cm","20(1 − 1/∛2) cm","20(1 − 1/√2) cm"],"explanationHi":"ऊपरी शंकु का आयतन आधा होना चाहिए, अतः उसकी ऊँचाई 20 × ∛(1/2) = 20/∛2 है। काट आधार से 20 − 20/∛2 = 20(1 − 1/∛2) cm ऊपर है; 20/∛2 शीर्ष से मापी गई दूरी है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-147","question":"A triangle has sides 13 cm, 14 cm and 15 cm. What is the ratio of its circumradius to its inradius?","options":["2 : 1","65 : 16","13 : 8","65 : 32"],"answer":3,"explanation":"Area = 84 (Heron), r = 84/21 = 4 and R = abc/4Δ = 2,730/336 = 65/8, so R : r = 65 : 32. Dividing by the full perimeter for r gives 2 and the ratio 65 : 16; 2 : 1 holds only for an equilateral triangle.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक त्रिभुज की भुजाएँ 13 cm, 14 cm और 15 cm हैं। उसकी परिवृत्त त्रिज्या और अंतःत्रिज्या का अनुपात क्या है?","optionsHi":["2 : 1","65 : 16","13 : 8","65 : 32"],"explanationHi":"क्षेत्रफल = 84 (हीरोन), r = 84/21 = 4 और R = abc/4Δ = 2,730/336 = 65/8, अतः R : r = 65 : 32। r के लिए पूरे परिमाप से भाग देने पर 2 और अनुपात 65 : 16 आता है; 2 : 1 केवल समबाहु त्रिभुज के लिए सही है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-148","question":"A rectangular park 60 m × 40 m has two roads, each 3 m wide, running through its middle, one parallel to each side. What does it cost to gravel the roads at ₹12 per m²?","options":["₹3,600","₹3,492","₹3,384","₹3,708"],"answer":1,"explanation":"Road area = 3×60 + 3×40 − 3×3 = 291 m² (the 9 m² crossing is counted twice otherwise), so cost = ₹3,492. Forgetting the overlap gives ₹3,600.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"60 m × 40 m के एक आयताकार पार्क के बीच से दो सड़कें गुजरती हैं, प्रत्येक 3 m चौड़ी, और प्रत्येक एक भुजा के समांतर। ₹12 प्रति m² की दर से सड़कों पर बजरी डलवाने का खर्च क्या है?","optionsHi":["₹3,600","₹3,492","₹3,384","₹3,708"],"explanationHi":"सड़कों का क्षेत्रफल = 3×60 + 3×40 − 3×3 = 291 m² (9 m² का कटान वाला भाग अन्यथा दो बार गिना जाता), अतः खर्च = ₹3,492। कटान को न घटाने पर ₹3,600 आता है।","subtopic":"paths-fields"},
  {"id":"quant-mensuration-149","question":"A bucket is a frustum of a cone with top radius 21 cm, bottom radius 14 cm and depth 24 cm. How many litres does it hold? (π = 22/7)","options":["23.1 L","16.016 L","33.264 L","23.41 L"],"answer":3,"explanation":"V = (πh/3)(R² + r² + Rr) = (22/7)(8)(441 + 196 + 294) = 23,408 cm³ = 23.408 L. A cylinder of the mean radius 17.5 cm gives 23.1 L; dropping the Rr term gives 16.016 L.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बाल्टी शंकु का छिन्नक है जिसकी ऊपरी त्रिज्या 21 cm, निचली त्रिज्या 14 cm और गहराई 24 cm है। उसमें कितने लीटर पानी आता है? (π = 22/7)","optionsHi":["23.1 L","16.016 L","33.264 L","23.41 L"],"explanationHi":"V = (πh/3)(R² + r² + Rr) = (22/7)(8)(441 + 196 + 294) = 23,408 cm³ = 23.408 L। माध्य त्रिज्या 17.5 cm वाले बेलन से 23.1 L आता है; Rr पद छोड़ देने पर 16.016 L।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-150","question":"A solid metal sphere of radius 9 cm is melted and drawn into a wire of diameter 2 mm. How long is the wire?","options":["243 m","972 m","3,888 m","97.2 m"],"answer":1,"explanation":"(4/3)π(9³) = 972π cm³; the wire's cross-section is π(0.1)² = 0.01π cm², so its length is 97,200 cm = 972 m. Using 2 mm as the radius gives 243 m.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"9 cm त्रिज्या वाले एक ठोस धातु के गोले को पिघलाकर 2 mm व्यास का तार खींचा जाता है। तार की लंबाई कितनी है?","optionsHi":["243 m","972 m","3,888 m","97.2 m"],"explanationHi":"(4/3)π(9³) = 972π cm³; तार की अनुप्रस्थ काट π(0.1)² = 0.01π cm² है, अतः लंबाई 97,200 cm = 972 m। 2 mm को त्रिज्या मानने पर 243 m आता है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-151","question":"A right circular cone is cut by a plane parallel to its base at one-third of its height measured from the vertex. What is the ratio of the volume of the small cone to that of the frustum left?","options":["1 : 26","1 : 27","1 : 8","1 : 9"],"answer":0,"explanation":"The small cone is similar with scale 1/3, so its volume is 1/27 of the whole and the frustum is 26/27: ratio 1 : 26. 1 : 27 compares with the whole cone, and 1 : 9 uses the area ratio.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक लंब वृत्तीय शंकु को शीर्ष से मापी गई उसकी ऊँचाई के एक-तिहाई पर आधार के समांतर तल से काटा जाता है। छोटे शंकु के आयतन और बचे हुए छिन्नक के आयतन का अनुपात क्या है?","optionsHi":["1 : 26","1 : 27","1 : 8","1 : 9"],"explanationHi":"छोटा शंकु 1/3 के स्केल पर समरूप है, अतः उसका आयतन पूरे का 1/27 है और छिन्नक 26/27 है: अनुपात 1 : 26। 1 : 27 पूरे शंकु से तुलना है, और 1 : 9 में क्षेत्रफल का अनुपात लिया गया है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-152","question":"A hemispherical bowl of internal radius 9 cm is full of liquid. The liquid is poured into cylindrical bottles of radius 1.5 cm and height 4 cm. How many bottles are filled?","options":["108","27","54","13"],"answer":2,"explanation":"Bowl = (2/3)π(729) = 486π; bottle = π(1.5)²(4) = 9π, so 54 bottles. Using the full sphere gives 108, and using the bottle's diameter as radius gives 13.5, i.e. 13.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"9 cm आंतरिक त्रिज्या वाला एक अर्धगोलाकार कटोरा द्रव से पूरा भरा है। द्रव को 1.5 cm त्रिज्या और 4 cm ऊँचाई वाली बेलनाकार बोतलों में उँडेला जाता है। कितनी बोतलें भरती हैं?","optionsHi":["108","27","54","13"],"explanationHi":"कटोरा = (2/3)π(729) = 486π; बोतल = π(1.5)²(4) = 9π, अतः 54 बोतलें। पूरा गोला लेने पर 108 आता है, और बोतल के व्यास को त्रिज्या मानने पर 13.5, यानी 13।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-153","question":"The radius of a closed cylinder is increased by 20% and its height is decreased by 20%. What happens to its volume and its curved surface area respectively?","options":["No change in either","+15.2% and no change","+15.2% and −4%","+20% and −4%"],"answer":2,"explanation":"Volume ∝ r²h: 1.44 × 0.8 = 1.152, so +15.2%. Curved area ∝ rh: 1.2 × 0.8 = 0.96, so −4%. The +20% − 20% = 0 shortcut is the trap.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बंद बेलन की त्रिज्या में 20% की वृद्धि और ऊँचाई में 20% की कमी की जाती है। उसके आयतन और वक्र पृष्ठीय क्षेत्रफल का क्रमशः क्या होगा?","optionsHi":["किसी में भी कोई परिवर्तन नहीं","+15.2% और कोई परिवर्तन नहीं","+15.2% और −4%","+20% और −4%"],"explanationHi":"आयतन ∝ r²h: 1.44 × 0.8 = 1.152, अतः +15.2%। वक्र क्षेत्रफल ∝ rh: 1.2 × 0.8 = 0.96, अतः −4%। +20% − 20% = 0 वाला शॉर्टकट जाल है।","subtopic":"percent-change-dimensions"},
  {"id":"quant-mensuration-154","question":"A rhombus has a perimeter of 52 cm and one diagonal of 24 cm. What is its area?","options":["120 cm²","240 cm²","156 cm²","60 cm²"],"answer":0,"explanation":"Side = 13; half-diagonals 12 and √(169 − 144) = 5, so the other diagonal is 10 and area = 24×10/2 = 120 cm². Forgetting the ½ gives 240.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक समचतुर्भुज का परिमाप 52 cm और एक विकर्ण 24 cm है। उसका क्षेत्रफल क्या है?","optionsHi":["120 cm²","240 cm²","156 cm²","60 cm²"],"explanationHi":"भुजा = 13; आधे विकर्ण 12 और √(169 − 144) = 5 हैं, अतः दूसरा विकर्ण 10 है और क्षेत्रफल = 24×10/2 = 120 cm²। ½ छूट जाने पर 240 आता है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-155","question":"A circle is inscribed in an equilateral triangle of side 12√3 cm, and a square is inscribed in that circle. What is the area of the square?","options":["144 cm²","288 cm²","36 cm²","72 cm²"],"answer":3,"explanation":"Inradius = a/(2√3) = 6, so the square's diagonal is 12 and its area is 12²/2 = 72 cm². Taking 12 as the side gives 144; using the circumradius 12 gives 288.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"12√3 cm भुजा वाले समबाहु त्रिभुज में एक वृत्त अंतर्गत खींचा गया है, और उस वृत्त में एक वर्ग अंतर्गत खींचा गया है। वर्ग का क्षेत्रफल क्या है?","optionsHi":["144 cm²","288 cm²","36 cm²","72 cm²"],"explanationHi":"अंतःत्रिज्या = a/(2√3) = 6, अतः वर्ग का विकर्ण 12 है और उसका क्षेत्रफल 12²/2 = 72 cm² है। 12 को भुजा मानने पर 144 आता है; परिवृत्त त्रिज्या 12 लेने पर 288।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-156","question":"Water flows at 5 km/h through a pipe of internal diameter 14 cm into a cylindrical tank of radius 7 m. How long does it take the water level in the tank to rise by 1.5 m?","options":["45 minutes","12 hours","3 hours","1.5 hours"],"answer":2,"explanation":"Tank needs π(49)(1.5) = 73.5π m³; the pipe delivers π(0.07)²(5,000) = 24.5π m³ per hour, so 3 hours. Using 14 cm as the radius gives 45 minutes.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"14 cm आंतरिक व्यास वाले पाइप से 5 km/h की चाल से पानी 7 m त्रिज्या वाली बेलनाकार टंकी में बहता है। टंकी में पानी का स्तर 1.5 m बढ़ने में कितना समय लगेगा?","optionsHi":["45 मिनट","12 घंटे","3 घंटे","1.5 घंटे"],"explanationHi":"टंकी को π(49)(1.5) = 73.5π m³ चाहिए; पाइप प्रति घंटे π(0.07)²(5,000) = 24.5π m³ देता है, अतः 3 घंटे। 14 cm को त्रिज्या मानने पर 45 मिनट आता है।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-157","question":"The sum of the lengths of all 12 edges of a cuboid is 116 cm and its total surface area is 552 cm². What is the length of its longest diagonal?","options":["17 cm","29 cm","23.77 cm","16.22 cm"],"answer":0,"explanation":"l + b + h = 29, and l² + b² + h² = 29² − 2(lb + bh + hl) = 841 − 552 = 289, so the diagonal is 17 cm. Subtracting only half the surface area gives √565 ≈ 23.77.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"एक घनाभ के सभी 12 किनारों की लंबाइयों का योग 116 cm है और उसका कुल पृष्ठीय क्षेत्रफल 552 cm² है। उसके सबसे लंबे विकर्ण की लंबाई क्या है?","optionsHi":["17 cm","29 cm","23.77 cm","16.22 cm"],"explanationHi":"l + b + h = 29, और l² + b² + h² = 29² − 2(lb + bh + hl) = 841 − 552 = 289, अतः विकर्ण 17 cm है। केवल आधा पृष्ठीय क्षेत्रफल घटाने पर √565 ≈ 23.77 आता है।","subtopic":"cube-cuboid"},
  {"id":"quant-mensuration-158","question":"The minute hand of a clock is 21 cm long. What area does it sweep between 9:10 am and 9:35 am? (π = 22/7)","options":["577.5 cm²","55 cm²","1,155 cm²","462 cm²"],"answer":0,"explanation":"25 minutes = 150°, so area = (150/360)(22/7)(21²) = 577.5 cm². 55 cm is the arc length, not the area.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक घड़ी की मिनट की सुई 21 cm लंबी है। वह सुबह 9:10 से 9:35 के बीच कितना क्षेत्रफल तय करती है? (π = 22/7)","optionsHi":["577.5 cm²","55 cm²","1,155 cm²","462 cm²"],"explanationHi":"25 मिनट = 150°, अतः क्षेत्रफल = (150/360)(22/7)(21²) = 577.5 cm²। 55 cm चाप की लंबाई है, क्षेत्रफल नहीं।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-159","question":"A right circular cylinder of height 12 cm stands on the base of a cone of height 30 cm and base radius 10 cm, with its top rim touching the cone's slant surface. What is the cylinder's volume?","options":["192π cm³","432π cm³","1,000π cm³","300π cm³"],"answer":1,"explanation":"At height 12 the cone's radius is 10 × (30 − 12)/30 = 6, so V = π(36)(12) = 432π. Using 10 × 12/30 = 4 (measuring from the wrong end) gives 192π.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"12 cm ऊँचाई वाला एक लंब वृत्तीय बेलन 30 cm ऊँचाई और 10 cm आधार त्रिज्या वाले शंकु के आधार पर खड़ा है, और उसके ऊपरी किनारे शंकु की तिर्यक सतह को छूते हैं। बेलन का आयतन क्या है?","optionsHi":["192π cm³","432π cm³","1,000π cm³","300π cm³"],"explanationHi":"12 की ऊँचाई पर शंकु की त्रिज्या 10 × (30 − 12)/30 = 6 है, अतः V = π(36)(12) = 432π। 10 × 12/30 = 4 लेने पर (गलत सिरे से मापने से) 192π आता है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-160","question":"A conical tent is 8 m high with a base radius of 6 m. How many metres of canvas 3 m wide are needed to make it (ignore wastage)? (π = 22/7)","options":["50.29 m","100.57 m","31.43 m","62.86 m"],"answer":3,"explanation":"Slant height = √(64 + 36) = 10, curved area = π(6)(10) = 188.57 m², length = 188.57/3 = 62.86 m. Using the height 8 instead of the slant gives 50.29 m; adding the floor area gives 100.57 m.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक शंक्वाकार तंबू 8 m ऊँचा है और उसकी आधार त्रिज्या 6 m है। उसे बनाने के लिए 3 m चौड़े कैनवास की कितने मीटर लंबाई चाहिए (बर्बादी को छोड़कर)? (π = 22/7)","optionsHi":["50.29 m","100.57 m","31.43 m","62.86 m"],"explanationHi":"तिर्यक ऊँचाई = √(64 + 36) = 10, वक्र क्षेत्रफल = π(6)(10) = 188.57 m², लंबाई = 188.57/3 = 62.86 m। तिर्यक ऊँचाई के बजाय ऊँचाई 8 लेने पर 50.29 m आता है; फर्श का क्षेत्रफल जोड़ने पर 100.57 m।","subtopic":"cylinder-cone-sphere"},
  {"id":"quant-mensuration-161","question":"A sphere fits exactly inside a cube, touching all six faces. What percentage of the cube's volume is empty? (π = 22/7)","options":["52.38%","47.62%","21.43%","33.33%"],"answer":1,"explanation":"Sphere/cube = (4/3)π(a/2)³ / a³ = π/6 = 11/21, so the empty part is 10/21 ≈ 47.62%. 52.38% is the filled part, and 21.43% is the 2-D circle-in-square answer.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक गोला घन के अंदर ठीक-ठीक बैठता है और उसके छहों फलकों को छूता है। घन के आयतन का कितना प्रतिशत खाली है? (π = 22/7)","optionsHi":["52.38%","47.62%","21.43%","33.33%"],"explanationHi":"गोला/घन = (4/3)π(a/2)³ / a³ = π/6 = 11/21, अतः खाली भाग 10/21 ≈ 47.62% है। 52.38% भरा हुआ भाग है, और 21.43% वर्ग में वृत्त (द्विविमीय) वाला उत्तर है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-162","question":"A trapezium has parallel sides of 25 cm and 11 cm and non-parallel sides of 13 cm and 15 cm. What is its area?","options":["216 cm²","234 cm²","270 cm²","252 cm²"],"answer":0,"explanation":"Sliding the legs together makes a 13-14-15 triangle (area 84), so the height is 2×84/14 = 12 and area = (25 + 11)/2 × 12 = 216 cm². Using a leg (13 or 15) as the height gives 234 or 270.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक समलंब चतुर्भुज की समांतर भुजाएँ 25 cm और 11 cm तथा असमांतर भुजाएँ 13 cm और 15 cm हैं। उसका क्षेत्रफल क्या है?","optionsHi":["216 cm²","234 cm²","270 cm²","252 cm²"],"explanationHi":"असमांतर भुजाओं को सटाने पर 13-14-15 का त्रिभुज बनता है (क्षेत्रफल 84), अतः ऊँचाई 2×84/14 = 12 है और क्षेत्रफल = (25 + 11)/2 × 12 = 216 cm²। किसी असमांतर भुजा (13 या 15) को ऊँचाई मानने पर 234 या 270 आता है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-163","question":"2 cm of rain falls on a field of 1.5 hectares, and all of it is collected in a tank 20 m long and 15 m wide. By how much does the water level in the tank rise?","options":["10 m","10 cm","1 m","100 m"],"answer":2,"explanation":"1.5 ha = 15,000 m², so the rain is 15,000 × 0.02 = 300 m³, and 300/(20×15) = 1 m. Taking a hectare as 1,000 m² gives 10 cm; forgetting to convert 2 cm to metres gives 100 m.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1.5 हेक्टेयर के खेत पर 2 cm वर्षा होती है और सारा पानी 20 m लंबी और 15 m चौड़ी टंकी में इकट्ठा किया जाता है। टंकी में पानी का स्तर कितना बढ़ेगा?","optionsHi":["10 m","10 cm","1 m","100 m"],"explanationHi":"1.5 हेक्टेयर = 15,000 m², अतः वर्षा = 15,000 × 0.02 = 300 m³, और 300/(20×15) = 1 m। हेक्टेयर को 1,000 m² मानने पर 10 cm आता है; 2 cm को मीटर में बदलना भूलने पर 100 m।","subtopic":"melting-recasting"},
  {"id":"quant-mensuration-164","question":"A wire bent into a square encloses 121 cm². If the same wire is bent into a circle, what area will it enclose? (π = 22/7)","options":["121 cm²","616 cm²","154 cm²","38.5 cm²"],"answer":2,"explanation":"Side 11, so the wire is 44 cm; 2πr = 44 gives r = 7 and area 154 cm². Taking 14 as the radius (it is the diameter) gives 616.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक तार को वर्ग के आकार में मोड़ने पर वह 121 cm² क्षेत्रफल घेरता है। यदि उसी तार को वृत्त के आकार में मोड़ा जाए, तो वह कितना क्षेत्रफल घेरेगा? (π = 22/7)","optionsHi":["121 cm²","616 cm²","154 cm²","38.5 cm²"],"explanationHi":"भुजा 11, अतः तार 44 cm का है; 2πr = 44 से r = 7 और क्षेत्रफल 154 cm²। 14 को त्रिज्या मानने पर (वह व्यास है) 616 आता है।","subtopic":"circles-sectors"},
  {"id":"quant-mensuration-165","question":"A hollow iron pipe is 21 cm long, its external diameter is 8 cm and the metal is 1 cm thick. If iron weighs 8 g/cm³, what does the pipe weigh? (π = 22/7)","options":["1.98 kg","14.784 kg","4.752 kg","3.696 kg"],"answer":3,"explanation":"Outer radius 4, inner radius 3, so volume = (22/7)(21)(16 − 9) = 462 cm³ and weight = 3,696 g. Subtracting the thickness from the diameter only once (inner radius 3.5) gives 1.98 kg.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक खोखला लोहे का पाइप 21 cm लंबा है, उसका बाहरी व्यास 8 cm है और धातु 1 cm मोटी है। यदि लोहे का भार 8 g/cm³ है, तो पाइप का भार क्या है? (π = 22/7)","optionsHi":["1.98 kg","14.784 kg","4.752 kg","3.696 kg"],"explanationHi":"बाहरी त्रिज्या 4, भीतरी त्रिज्या 3, अतः आयतन = (22/7)(21)(16 − 9) = 462 cm³ और भार = 3,696 g। व्यास में से मोटाई केवल एक बार घटाने पर (भीतरी त्रिज्या 3.5) 1.98 kg आता है।","subtopic":"frustum-composite"},
  {"id":"quant-mensuration-166","question":"The sides of a triangle are in the ratio 5 : 12 : 13 and its perimeter is 120 cm. What is the length of the altitude drawn to its longest side?","options":["120/13 cm","240/13 cm","20 cm","24 cm"],"answer":1,"explanation":"The sides are 20, 48, 52 — a right triangle with area 20×48/2 = 480. Altitude to 52 = 2×480/52 = 240/13 ≈ 18.46 cm. Forgetting the factor 2 gives 120/13.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक त्रिभुज की भुजाओं का अनुपात 5 : 12 : 13 है और उसका परिमाप 120 cm है। सबसे लंबी भुजा पर डाले गए लंब की लंबाई क्या है?","optionsHi":["120/13 cm","240/13 cm","20 cm","24 cm"],"explanationHi":"भुजाएँ 20, 48, 52 हैं — एक समकोण त्रिभुज जिसका क्षेत्रफल 20×48/2 = 480 है। 52 पर लंब = 2×480/52 = 240/13 ≈ 18.46 cm। गुणक 2 छूट जाने पर 120/13 आता है।","subtopic":"triangles-quadrilaterals"},
  {"id":"quant-mensuration-167","question":"An isosceles triangle has equal sides of 17 cm and a base of 16 cm. What is the ratio of its inradius to its circumradius?","options":["12 : 17","8 : 17","144 : 289","15 : 34"],"answer":2,"explanation":"The height is 15, so area = 120 and s = 25, giving r = 120/25 = 4.8. R = (17 × 17 × 16)/(4 × 120) = 289/30. Hence r : R = 144/30 : 289/30 = 144 : 289.","difficulty":"very-hard","questionHi":"एक समद्विबाहु त्रिभुज की बराबर भुजाएँ 17 cm और आधार 16 cm है। उसकी अंतःत्रिज्या और परित्रिज्या का अनुपात क्या है?","optionsHi":["12 : 17","8 : 17","144 : 289","15 : 34"],"explanationHi":"ऊँचाई 15 है, अतः क्षेत्रफल = 120 और s = 25, जिससे r = 120/25 = 4.8। R = (17 × 17 × 16)/(4 × 120) = 289/30। इसलिए r : R = 144/30 : 289/30 = 144 : 289।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-168","question":"A rhombus has a side of 13 cm and one diagonal of 24 cm. What is the perpendicular distance between a pair of its opposite sides?","options":["9.23 cm","10 cm","9.6 cm","12 cm"],"answer":0,"explanation":"Half the other diagonal is √(13² − 12²) = 5, so it is 10 cm and the area is ½ × 24 × 10 = 120 cm². Distance between opposite sides = area/side = 120/13 ≈ 9.23 cm.","difficulty":"hard","questionHi":"एक समचतुर्भुज की भुजा 13 cm और एक विकर्ण 24 cm है। उसकी आमने-सामने की भुजाओं के बीच की लंबवत दूरी क्या है?","optionsHi":["9.23 cm","10 cm","9.6 cm","12 cm"],"explanationHi":"दूसरे विकर्ण का आधा √(13² − 12²) = 5 है, अतः वह 10 cm है और क्षेत्रफल ½ × 24 × 10 = 120 cm²। आमने-सामने की भुजाओं के बीच की दूरी = क्षेत्रफल/भुजा = 120/13 ≈ 9.23 cm।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-169","question":"In a trapezium the parallel sides are 25 cm and 11 cm and the non-parallel sides are 15 cm and 13 cm. What is its area?","options":["234 cm²","270 cm²","180 cm²","216 cm²"],"answer":3,"explanation":"Slide one leg across to form a triangle with sides 14, 13, 15 (14 = 25 − 11). Its area is 84, so the height is 2 × 84/14 = 12 and the trapezium area is ½ × 36 × 12 = 216 cm².","difficulty":"very-hard","questionHi":"एक समलंब चतुर्भुज की समांतर भुजाएँ 25 cm और 11 cm तथा असमांतर भुजाएँ 15 cm और 13 cm हैं। उसका क्षेत्रफल क्या है?","optionsHi":["234 cm²","270 cm²","180 cm²","216 cm²"],"explanationHi":"एक असमांतर भुजा को खिसकाने पर भुजाओं 14, 13, 15 (14 = 25 − 11) का त्रिभुज बनता है। इसका क्षेत्रफल 84 है, अतः ऊँचाई 2 × 84/14 = 12 और समलंब का क्षेत्रफल ½ × 36 × 12 = 216 cm²।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-170","question":"A circle is inscribed in a square, a second square is inscribed in that circle, and a second circle is inscribed in the second square. What is the ratio of the area of the outer square to the area of the inner circle?","options":["4 : π","8 : π","2 : π","16 : π"],"answer":1,"explanation":"Let the outer square have side 2a, so the first circle has radius a. The second square has diagonal 2a and side a√2, so the inner circle has radius a/√2 and area πa²/2. Ratio = 4a² : πa²/2 = 8 : π.","difficulty":"very-hard","questionHi":"एक वर्ग में एक वृत्त अंतःस्थापित है, उस वृत्त में दूसरा वर्ग अंतःस्थापित है और दूसरे वर्ग में दूसरा वृत्त अंतःस्थापित है। बाहरी वर्ग के क्षेत्रफल और भीतरी वृत्त के क्षेत्रफल का अनुपात क्या है?","optionsHi":["4 : π","8 : π","2 : π","16 : π"],"explanationHi":"बाहरी वर्ग की भुजा 2a मानें, तो पहले वृत्त की त्रिज्या a है। दूसरे वर्ग का विकर्ण 2a और भुजा a√2 है, इसलिए भीतरी वृत्त की त्रिज्या a/√2 और क्षेत्रफल πa²/2। अनुपात = 4a² : πa²/2 = 8 : π।","subtopic":"circles-sectors","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-171","question":"Two circles of radii 15 cm and 20 cm have their centres 25 cm apart and intersect at two points. What is the length of their common chord?","options":["12 cm","24 cm","30 cm","25 cm"],"answer":1,"explanation":"Since 15² + 20² = 25², the two radii to an intersection point are perpendicular, forming a right triangle with hypotenuse 25. The common chord is twice the altitude: 2 × (15 × 20)/25 = 24 cm.","difficulty":"very-hard","questionHi":"15 cm और 20 cm त्रिज्या वाले दो वृत्तों के केंद्र 25 cm दूर हैं और वे दो बिंदुओं पर प्रतिच्छेद करते हैं। उनकी उभयनिष्ठ जीवा की लंबाई क्या है?","optionsHi":["12 cm","24 cm","30 cm","25 cm"],"explanationHi":"चूँकि 15² + 20² = 25², प्रतिच्छेद बिंदु तक की दोनों त्रिज्याएँ लंबवत हैं और कर्ण 25 वाला समकोण त्रिभुज बनता है। उभयनिष्ठ जीवा शीर्षलंब की दुगुनी है: 2 × (15 × 20)/25 = 24 cm।","subtopic":"circles-sectors","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-172","question":"A sector of angle 216° is cut from a circle of radius 10 cm and its straight edges are joined to form a cone. What is the volume of the cone?","options":["288π cm³","128π cm³","72π cm³","96π cm³"],"answer":3,"explanation":"The arc 2π × 10 × 216/360 = 12π becomes the base circumference, so r = 6 and the slant height is 10, giving h = 8. Volume = ⅓π × 36 × 8 = 96π cm³; omitting the ⅓ gives 288π.","difficulty":"hard","questionHi":"10 cm त्रिज्या वाले वृत्त से 216° कोण का एक त्रिज्यखंड काटा जाता है और उसके सीधे किनारों को जोड़कर एक शंकु बनाया जाता है। शंकु का आयतन क्या है?","optionsHi":["288π cm³","128π cm³","72π cm³","96π cm³"],"explanationHi":"चाप 2π × 10 × 216/360 = 12π आधार की परिधि बनता है, अतः r = 6 और तिर्यक ऊँचाई 10, जिससे h = 8। आयतन = ⅓π × 36 × 8 = 96π cm³; ⅓ छोड़ने पर 288π आता है।","subtopic":"cylinder-cone-sphere","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-173","question":"In a circle of radius 13 cm two parallel chords have lengths 10 cm and 24 cm. What is the distance between them?","options":["7 cm or 17 cm","7 cm only","17 cm only","13 cm or 7 cm"],"answer":0,"explanation":"The chords are 12 cm and 5 cm from the centre. On the same side they are 12 − 5 = 7 cm apart; on opposite sides 12 + 5 = 17 cm. Both configurations are possible.","difficulty":"very-hard","questionHi":"13 cm त्रिज्या वाले वृत्त में दो समांतर जीवाओं की लंबाई 10 cm और 24 cm है। उनके बीच की दूरी क्या है?","optionsHi":["7 cm या 17 cm","केवल 7 cm","केवल 17 cm","13 cm या 7 cm"],"explanationHi":"जीवाएँ केंद्र से क्रमशः 12 cm और 5 cm दूर हैं। एक ही ओर होने पर उनके बीच 12 − 5 = 7 cm और विपरीत ओर होने पर 12 + 5 = 17 cm की दूरी है। दोनों स्थितियाँ संभव हैं।","subtopic":"circles-sectors","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-174","question":"The minute hand of a clock is 14 cm long. What area does it sweep from 3:10 to 3:40? (π = 22/7)","options":["154 cm²","616 cm²","308 cm²","205.33 cm²"],"answer":2,"explanation":"Thirty minutes is half a revolution (180°), so the area is half a circle of radius 14: ½ × 22/7 × 196 = 308 cm².","difficulty":"moderate","questionHi":"एक घड़ी की मिनट की सुई 14 cm लंबी है। वह 3:10 से 3:40 तक कितना क्षेत्रफल पार करती है? (π = 22/7)","optionsHi":["154 cm²","616 cm²","308 cm²","205.33 cm²"],"explanationHi":"तीस मिनट आधा चक्कर (180°) है, अतः क्षेत्रफल 14 त्रिज्या वाले वृत्त का आधा है: ½ × 22/7 × 196 = 308 cm²।","subtopic":"circles-sectors","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-175","question":"The area between two concentric circles is 462 cm². A chord of the outer circle touches the inner circle. What is the length of this chord? (π = 22/7)","options":["7√3 cm","14√2 cm","21√2 cm","14√3 cm"],"answer":3,"explanation":"π(R² − r²) = 462 gives R² − r² = 147. The half-chord is √(R² − r²) = √147 = 7√3, so the chord is 14√3 cm.","difficulty":"very-hard","questionHi":"दो संकेंद्री वृत्तों के बीच का क्षेत्रफल 462 cm² है। बाहरी वृत्त की एक जीवा भीतरी वृत्त को स्पर्श करती है। इस जीवा की लंबाई क्या है? (π = 22/7)","optionsHi":["7√3 cm","14√2 cm","21√2 cm","14√3 cm"],"explanationHi":"π(R² − r²) = 462 से R² − r² = 147। आधी जीवा √(R² − r²) = √147 = 7√3 है, अतः जीवा 14√3 cm है।","subtopic":"circles-sectors","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-176","question":"A rectangular park measures 40 m by 30 m. A path of uniform width runs inside all along its boundary, and its area is exactly half the area of the park. What is the width of the path?","options":["4 m","5 m","6 m","7.5 m"],"answer":1,"explanation":"The inner part must also be 600 m²: (40 − 2x)(30 − 2x) = 600 gives x² − 35x + 150 = 0, so x = 5 (30 is impossible). Check: 30 × 20 = 600.","difficulty":"hard","questionHi":"एक आयताकार पार्क की माप 40 m × 30 m है। उसकी सीमा के भीतर चारों ओर एकसमान चौड़ाई का एक रास्ता है, जिसका क्षेत्रफल पार्क के क्षेत्रफल का ठीक आधा है। रास्ते की चौड़ाई क्या है?","optionsHi":["4 m","5 m","6 m","7.5 m"],"explanationHi":"भीतरी भाग का क्षेत्रफल भी 600 m² होना चाहिए: (40 − 2x)(30 − 2x) = 600 से x² − 35x + 150 = 0, अतः x = 5 (30 असंभव है)। जाँच: 30 × 20 = 600।","subtopic":"paths-fields","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-177","question":"Two roads, each 4 m wide, cross at the centre of a rectangular field 60 m long and 40 m wide, one parallel to each side. What is the cost of gravelling the roads at ₹25 per m²?","options":["₹10,000","₹9,200","₹9,600","₹8,400"],"answer":2,"explanation":"Area of roads = 4 × 60 + 4 × 40 − 4 × 4 = 384 m², since the central 4 × 4 square is counted twice. Cost = 384 × 25 = ₹9,600.","difficulty":"moderate","questionHi":"60 m लंबे और 40 m चौड़े एक आयताकार खेत के केंद्र पर 4 m चौड़ी दो सड़कें एक-दूसरे को काटती हैं, प्रत्येक एक भुजा के समांतर है। ₹25 प्रति m² की दर से सड़कों पर बजरी बिछाने का खर्च क्या है?","optionsHi":["₹10,000","₹9,200","₹9,600","₹8,400"],"explanationHi":"सड़कों का क्षेत्रफल = 4 × 60 + 4 × 40 − 4 × 4 = 384 m², क्योंकि बीच का 4 × 4 वर्ग दो बार गिना जाता है। खर्च = 384 × 25 = ₹9,600।","subtopic":"paths-fields","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-178","question":"A rectangular park is surrounded on the outside by a 2 m wide path. A jogger runs once along the outer edge of the path instead of along the park's boundary. How much farther does he run?","options":["16 m","8 m","12 m","32 m"],"answer":0,"explanation":"The outer rectangle is 2w longer and 2w wider on each dimension, so its perimeter is larger by 8w = 8 × 2 = 16 m, whatever the park's size.","difficulty":"moderate","questionHi":"एक आयताकार पार्क के बाहर चारों ओर 2 m चौड़ा रास्ता है। एक धावक पार्क की सीमा के बजाय रास्ते के बाहरी किनारे पर एक चक्कर दौड़ता है। वह कितनी अधिक दूरी दौड़ता है?","optionsHi":["16 m","8 m","12 m","32 m"],"explanationHi":"बाहरी आयत की प्रत्येक विमा 2w बढ़ जाती है, इसलिए उसका परिमाप 8w = 8 × 2 = 16 m अधिक है, चाहे पार्क का आकार कुछ भी हो।","subtopic":"paths-fields","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-179","question":"A cube of side 8 cm has its top and bottom faces painted red and its other four faces painted blue. It is cut into 512 unit cubes. How many unit cubes have exactly one painted face, and that face is blue?","options":["144","216","192","96"],"answer":0,"explanation":"A unit cube with exactly one painted face lies in the interior of a face, i.e. (8 − 2)² = 36 per face. The four blue faces give 4 × 36 = 144; 216 counts all six faces.","difficulty":"very-hard","questionHi":"8 cm भुजा वाले एक घन के ऊपरी और निचले फलक लाल तथा शेष चार फलक नीले रंग से रंगे गए हैं। उसे 512 इकाई घनों में काटा जाता है। कितने इकाई घनों का ठीक एक फलक रंगा है और वह नीला है?","optionsHi":["144","216","192","96"],"explanationHi":"ठीक एक रंगे फलक वाला इकाई घन किसी फलक के भीतरी भाग में होता है, अर्थात् प्रति फलक (8 − 2)² = 36। चार नीले फलकों से 4 × 36 = 144; 216 में सभी छह फलक गिन लिए गए हैं।","subtopic":"cube-cuboid","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-180","question":"A cuboid has a space diagonal of 14 cm and the total length of all its 12 edges is 88 cm. What is its total surface area?","options":["484 cm²","196 cm²","288 cm²","144 cm²"],"answer":2,"explanation":"a + b + c = 88/4 = 22 and a² + b² + c² = 196. Surface area = 2(ab + bc + ca) = (a + b + c)² − (a² + b² + c²) = 484 − 196 = 288 cm².","difficulty":"hard","questionHi":"एक घनाभ का अंतःकर्ण 14 cm है और उसके सभी 12 किनारों की कुल लंबाई 88 cm है। उसका कुल पृष्ठीय क्षेत्रफल क्या है?","optionsHi":["484 cm²","196 cm²","288 cm²","144 cm²"],"explanationHi":"a + b + c = 88/4 = 22 और a² + b² + c² = 196। पृष्ठीय क्षेत्रफल = 2(ab + bc + ca) = (a + b + c)² − (a² + b² + c²) = 484 − 196 = 288 cm²।","subtopic":"cube-cuboid","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-181","question":"The edges of a cuboid are in the ratio 1 : 2 : 3 and its total surface area is 198 cm². What is its volume?","options":["216 cm³","162 cm³","108 cm³","144 cm³"],"answer":1,"explanation":"With edges x, 2x, 3x the surface area is 2(2 + 6 + 3)x² = 22x² = 198, so x = 3. Volume = 6x³ = 6 × 27 = 162 cm³.","difficulty":"moderate","questionHi":"एक घनाभ के किनारे 1 : 2 : 3 के अनुपात में हैं और उसका कुल पृष्ठीय क्षेत्रफल 198 cm² है। उसका आयतन क्या है?","optionsHi":["216 cm³","162 cm³","108 cm³","144 cm³"],"explanationHi":"किनारे x, 2x, 3x होने पर पृष्ठीय क्षेत्रफल 2(2 + 6 + 3)x² = 22x² = 198, अतः x = 3। आयतन = 6x³ = 6 × 27 = 162 cm³।","subtopic":"cube-cuboid","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-182","question":"Every edge of a cube is increased by 20%. What is the ratio of the percentage increase in its volume to the percentage increase in its total surface area?","options":["18 : 11","5 : 3","3 : 2","91 : 55"],"answer":3,"explanation":"Volume factor 1.2³ = 1.728 (increase 72.8%) and area factor 1.44 (increase 44%). The ratio is 72.8 : 44 = 91 : 55.","difficulty":"very-hard","questionHi":"एक घन के प्रत्येक किनारे में 20% की वृद्धि की जाती है। उसके आयतन में प्रतिशत वृद्धि और कुल पृष्ठीय क्षेत्रफल में प्रतिशत वृद्धि का अनुपात क्या है?","optionsHi":["18 : 11","5 : 3","3 : 2","91 : 55"],"explanationHi":"आयतन गुणक 1.2³ = 1.728 (वृद्धि 72.8%) और क्षेत्रफल गुणक 1.44 (वृद्धि 44%)। अनुपात 72.8 : 44 = 91 : 55।","subtopic":"cube-cuboid","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-183","question":"A cylindrical vessel of radius 7 cm and height 24 cm holds water 10 cm deep. A solid sphere of radius 7 cm is dropped in and sinks completely. What is the new depth of the water?","options":["17.5 cm","19 cm","19.33 cm","24 cm"],"answer":2,"explanation":"Rise = (4/3 × π × 343)/(π × 49) = 28/3 = 9.33 cm, so the new depth is 10 + 9.33 = 19.33 cm, which exceeds the sphere's 14 cm diameter, so it is fully submerged.","difficulty":"hard","questionHi":"7 cm त्रिज्या और 24 cm ऊँचाई वाले एक बेलनाकार बर्तन में 10 cm गहरा पानी भरा है। 7 cm त्रिज्या का एक ठोस गोला उसमें डाला जाता है और वह पूरी तरह डूब जाता है। पानी की नई गहराई क्या है?","optionsHi":["17.5 cm","19 cm","19.33 cm","24 cm"],"explanationHi":"वृद्धि = (4/3 × π × 343)/(π × 49) = 28/3 = 9.33 cm, अतः नई गहराई 10 + 9.33 = 19.33 cm है, जो गोले के 14 cm व्यास से अधिक है, अतः वह पूरा डूबा है।","subtopic":"cylinder-cone-sphere","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-184","question":"A right circular cone has base radius 5 cm and height 12 cm. What is the radius of the largest sphere that can be placed inside it?","options":["10/3 cm","5/2 cm","4 cm","60/13 cm"],"answer":0,"explanation":"The sphere's radius equals the inradius of the axial section (sides 13, 13, 10). Area = 60 and s = 18, so r = 60/18 = 10/3 cm.","difficulty":"very-hard","questionHi":"एक लंब वृत्तीय शंकु की आधार त्रिज्या 5 cm और ऊँचाई 12 cm है। उसके भीतर रखे जा सकने वाले सबसे बड़े गोले की त्रिज्या क्या है?","optionsHi":["10/3 cm","5/2 cm","4 cm","60/13 cm"],"explanationHi":"गोले की त्रिज्या अक्षीय परिच्छेद (भुजाएँ 13, 13, 10) की अंतःत्रिज्या के बराबर होती है। क्षेत्रफल = 60 और s = 18, अतः r = 60/18 = 10/3 cm।","subtopic":"cylinder-cone-sphere","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-185","question":"A capsule is a cylinder with a hemisphere attached at each end. Its radius is 3 cm and its total length is 20 cm. What is its volume?","options":["216π cm³","126π cm³","180π cm³","162π cm³"],"answer":3,"explanation":"The cylindrical part has length 20 − 2 × 3 = 14, so its volume is π × 9 × 14 = 126π. The two hemispheres form a sphere, 4/3 × π × 27 = 36π. Total 162π cm³.","difficulty":"hard","questionHi":"एक कैप्सूल एक बेलन है जिसके प्रत्येक सिरे पर एक अर्धगोला जुड़ा है। उसकी त्रिज्या 3 cm और कुल लंबाई 20 cm है। उसका आयतन क्या है?","optionsHi":["216π cm³","126π cm³","180π cm³","162π cm³"],"explanationHi":"बेलनाकार भाग की लंबाई 20 − 2 × 3 = 14 है, अतः उसका आयतन π × 9 × 14 = 126π है। दोनों अर्धगोले मिलकर एक गोला बनाते हैं, 4/3 × π × 27 = 36π। कुल 162π cm³।","subtopic":"frustum-composite","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-186","question":"A bucket is in the shape of a frustum of a cone with top radius 20 cm, bottom radius 10 cm and vertical height 24 cm. How many litres of water can it hold? (π = 22/7)","options":["8.8 litres","17.6 litres","26.4 litres","35.2 litres"],"answer":1,"explanation":"Volume = (πh/3)(R² + Rr + r²) = (22/7) × 8 × (400 + 200 + 100) = 17,600 cm³ = 17.6 litres.","difficulty":"hard","questionHi":"एक बाल्टी शंकु के छिन्नक के आकार की है, जिसकी ऊपरी त्रिज्या 20 cm, निचली त्रिज्या 10 cm और ऊर्ध्वाधर ऊँचाई 24 cm है। उसमें कितने लीटर पानी आ सकता है? (π = 22/7)","optionsHi":["8.8 लीटर","17.6 लीटर","26.4 लीटर","35.2 लीटर"],"explanationHi":"आयतन = (πh/3)(R² + Rr + r²) = (22/7) × 8 × (400 + 200 + 100) = 17,600 cm³ = 17.6 लीटर।","subtopic":"frustum-composite","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-187","question":"A cone of height 30 cm is cut by a plane parallel to its base at a height of 12 cm above the base. What is the ratio of the volume of the frustum to the volume of the small cone cut off from the top?","options":["98 : 125","98 : 27","27 : 98","5 : 2"],"answer":1,"explanation":"The small cone has height 18, so its volume is (18/30)³ = 27/125 of the whole. The frustum is 98/125, so the ratio is 98 : 27.","difficulty":"very-hard","questionHi":"30 cm ऊँचाई वाले एक शंकु को आधार के समांतर एक तल से आधार से 12 cm ऊपर काटा जाता है। छिन्नक के आयतन और ऊपर से कटे छोटे शंकु के आयतन का अनुपात क्या है?","optionsHi":["98 : 125","98 : 27","27 : 98","5 : 2"],"explanationHi":"छोटे शंकु की ऊँचाई 18 है, अतः उसका आयतन पूरे शंकु का (18/30)³ = 27/125 है। छिन्नक 98/125 है, इसलिए अनुपात 98 : 27।","subtopic":"frustum-composite","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-188","question":"A pyramid has a square base of side 12 cm and each of its four slant (lateral) edges is 11 cm long. What is its volume?","options":["384 cm³","1,008 cm³","288 cm³","336 cm³"],"answer":3,"explanation":"Half the base diagonal is 6√2, so h² = 11² − 72 = 49 and h = 7. Volume = ⅓ × 144 × 7 = 336 cm³.","difficulty":"hard","questionHi":"एक पिरामिड का आधार 12 cm भुजा वाला वर्ग है और उसके चारों तिर्यक (पार्श्व) किनारों में से प्रत्येक 11 cm लंबा है। उसका आयतन क्या है?","optionsHi":["384 cm³","1,008 cm³","288 cm³","336 cm³"],"explanationHi":"आधार के विकर्ण का आधा 6√2 है, अतः h² = 11² − 72 = 49 और h = 7। आयतन = ⅓ × 144 × 7 = 336 cm³।","subtopic":"frustum-composite","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-189","question":"A solid metal sphere of radius 9 cm is melted and drawn into a uniform wire of diameter 2 mm. What is the length of the wire?","options":["972 m","243 m","486 m","9,720 m"],"answer":0,"explanation":"Sphere volume = 4/3 × π × 729 = 972π cm³. Wire radius is 0.1 cm, so 972π = π × 0.01 × L, giving L = 97,200 cm = 972 m. Using the diameter as the radius would give 243 m.","difficulty":"hard","questionHi":"9 cm त्रिज्या के एक ठोस धातु के गोले को पिघलाकर 2 mm व्यास का एकसमान तार खींचा जाता है। तार की लंबाई क्या है?","optionsHi":["972 m","243 m","486 m","9,720 m"],"explanationHi":"गोले का आयतन = 4/3 × π × 729 = 972π cm³। तार की त्रिज्या 0.1 cm है, अतः 972π = π × 0.01 × L, जिससे L = 97,200 cm = 972 m। व्यास को त्रिज्या मानने पर 243 m आता।","subtopic":"melting-recasting","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-190","question":"Three solid metal cubes of edges 3 cm, 4 cm and 5 cm are melted and recast into a single cube. By what percentage is the total surface area reduced?","options":["25%","30%","28%","72%"],"answer":2,"explanation":"Volume = 27 + 64 + 125 = 216, so the new edge is 6 cm and its area is 216. The original areas total 54 + 96 + 150 = 300, so the reduction is 84/300 = 28%.","difficulty":"hard","questionHi":"3 cm, 4 cm और 5 cm किनारे वाले तीन ठोस धातु के घनों को पिघलाकर एक ही घन बनाया जाता है। कुल पृष्ठीय क्षेत्रफल कितने प्रतिशत घट जाता है?","optionsHi":["25%","30%","28%","72%"],"explanationHi":"आयतन = 27 + 64 + 125 = 216, अतः नया किनारा 6 cm और उसका क्षेत्रफल 216 है। मूल क्षेत्रफल कुल 54 + 96 + 150 = 300 हैं, इसलिए कमी 84/300 = 28%।","subtopic":"melting-recasting","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-191","question":"A cylindrical vessel of radius 10 cm contains water. A solid cone of base radius 6 cm and height 25 cm is dropped in and sinks completely. By how much does the water level rise?","options":["1 cm","4 cm","9 cm","3 cm"],"answer":3,"explanation":"Cone volume = ⅓ × π × 36 × 25 = 300π. This spreads over the vessel's base area 100π, so the rise is 3 cm. Forgetting the ⅓ gives 9 cm.","difficulty":"hard","questionHi":"10 cm त्रिज्या वाले एक बेलनाकार बर्तन में पानी भरा है। 6 cm आधार त्रिज्या और 25 cm ऊँचाई वाला एक ठोस शंकु उसमें डाला जाता है और पूरी तरह डूब जाता है। पानी का स्तर कितना ऊपर उठता है?","optionsHi":["1 cm","4 cm","9 cm","3 cm"],"explanationHi":"शंकु का आयतन = ⅓ × π × 36 × 25 = 300π। यह बर्तन के आधार क्षेत्रफल 100π पर फैलता है, अतः स्तर 3 cm बढ़ता है। ⅓ भूलने पर 9 cm आता है।","subtopic":"melting-recasting","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-192","question":"The length of a rectangle is increased by 20% and its breadth is decreased by x%, so that its area decreases by 4%. What is x?","options":["16%","20%","24%","25%"],"answer":1,"explanation":"1.2 × (1 − x/100) = 0.96 gives 1 − x/100 = 0.8, so x = 20%. The tempting 16% comes from 20 − 4.","difficulty":"moderate","questionHi":"एक आयत की लंबाई 20% बढ़ाई जाती है और उसकी चौड़ाई x% घटाई जाती है, जिससे उसका क्षेत्रफल 4% घट जाता है। x का मान क्या है?","optionsHi":["16%","20%","24%","25%"],"explanationHi":"1.2 × (1 − x/100) = 0.96 से 1 − x/100 = 0.8, अतः x = 20%। भ्रामक 16% का उत्तर 20 − 4 से आता है।","subtopic":"percent-change-dimensions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-193","question":"The radius of a cylinder is increased by 10% and its height is decreased by 19%. What is the change in its volume?","options":["1% decrease","2.1% decrease","1.99% decrease","1.99% increase"],"answer":2,"explanation":"Volume ∝ r²h, so the factor is 1.1² × 0.81 = 1.21 × 0.81 = 0.9801. The volume falls by 1.99%.","difficulty":"hard","questionHi":"एक बेलन की त्रिज्या 10% बढ़ाई जाती है और उसकी ऊँचाई 19% घटाई जाती है। उसके आयतन में क्या परिवर्तन होता है?","optionsHi":["1% की कमी","2.1% की कमी","1.99% की कमी","1.99% की वृद्धि"],"explanationHi":"आयतन ∝ r²h, अतः गुणक 1.1² × 0.81 = 1.21 × 0.81 = 0.9801। आयतन 1.99% घटता है।","subtopic":"percent-change-dimensions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-194","question":"The radius of a circle is decreased by 10%. By what percentage must the new radius then be increased to restore the original area?","options":["11.11%","23.46%","19%","10%"],"answer":0,"explanation":"The area returns to its original value only when the radius returns to its original value, i.e. a rise from 0.9r to r, which is 1/9 = 11.11%. The area itself fell by 19%, but that is not the answer asked.","difficulty":"moderate","questionHi":"एक वृत्त की त्रिज्या 10% घटाई जाती है। मूल क्षेत्रफल वापस पाने के लिए नई त्रिज्या को कितने प्रतिशत बढ़ाना होगा?","optionsHi":["11.11%","23.46%","19%","10%"],"explanationHi":"क्षेत्रफल तभी मूल मान पर लौटता है जब त्रिज्या अपने मूल मान पर लौटे, अर्थात् 0.9r से r तक वृद्धि, जो 1/9 = 11.11% है। क्षेत्रफल स्वयं 19% घटा था, पर वह पूछा गया उत्तर नहीं है।","subtopic":"percent-change-dimensions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-195","question":"The length of a cuboid is increased by 20% and its breadth by 25%. By what percentage must its height be decreased to keep the volume unchanged?","options":["33.33%","45%","50%","25%"],"answer":0,"explanation":"The length and breadth together multiply the volume by 1.2 × 1.25 = 1.5, so the height factor must be 1/1.5 = 2/3, a decrease of 33.33%. The sum 45% is the common wrong answer.","difficulty":"hard","questionHi":"एक घनाभ की लंबाई 20% और चौड़ाई 25% बढ़ाई जाती है। आयतन अपरिवर्तित रखने के लिए उसकी ऊँचाई कितने प्रतिशत घटानी होगी?","optionsHi":["33.33%","45%","50%","25%"],"explanationHi":"लंबाई और चौड़ाई मिलकर आयतन को 1.2 × 1.25 = 1.5 गुना कर देती हैं, इसलिए ऊँचाई का गुणक 1/1.5 = 2/3 होना चाहिए, अर्थात् 33.33% की कमी। 45% सामान्य गलत उत्तर है।","subtopic":"percent-change-dimensions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-196","question":"The total surface area of a sphere increases by 44%. By what percentage does its volume increase?","options":["66%","72%","72.8%","88.4%"],"answer":2,"explanation":"Area ∝ r², so r² rises by 1.44 and r by 1.2. Volume ∝ r³, so the factor is 1.2³ = 1.728, an increase of 72.8%.","difficulty":"hard","questionHi":"एक गोले का कुल पृष्ठीय क्षेत्रफल 44% बढ़ जाता है। उसके आयतन में कितने प्रतिशत की वृद्धि होती है?","optionsHi":["66%","72%","72.8%","88.4%"],"explanationHi":"क्षेत्रफल ∝ r², अतः r² 1.44 गुना और r 1.2 गुना होता है। आयतन ∝ r³, अतः गुणक 1.2³ = 1.728, अर्थात् 72.8% की वृद्धि।","subtopic":"percent-change-dimensions","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-197","question":"The medians of a triangle are 9 cm, 12 cm and 15 cm. What is the area of the triangle?","options":["54 cm²","72 cm²","81 cm²","108 cm²"],"answer":1,"explanation":"A triangle with sides equal to the medians has area ¾ of the original. The 9-12-15 triangle has area 54, so the original is 54 × 4/3 = 72 cm². The area 54 is that of the median triangle.","difficulty":"very-hard","questionHi":"एक त्रिभुज की माध्यिकाएँ 9 cm, 12 cm और 15 cm हैं। त्रिभुज का क्षेत्रफल क्या है?","optionsHi":["54 cm²","72 cm²","81 cm²","108 cm²"],"explanationHi":"जिस त्रिभुज की भुजाएँ माध्यिकाओं के बराबर हों उसका क्षेत्रफल मूल त्रिभुज का ¾ होता है। 9-12-15 त्रिभुज का क्षेत्रफल 54 है, अतः मूल त्रिभुज का क्षेत्रफल 54 × 4/3 = 72 cm²। 54 माध्यिका-त्रिभुज का क्षेत्रफल है।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-198","question":"In a right-angled triangle with legs 9 cm and 12 cm, what is the length of the bisector of the right angle, measured to the hypotenuse?","options":["7.2 cm","36/7 cm","6 cm","36√2/7 cm"],"answer":3,"explanation":"Splitting the area: ½ × 9 × 12 = ½ × 9 × d sin45° + ½ × 12 × d sin45°, so 54 = (21/2)(d/√2) and d = 36√2/7 ≈ 7.27 cm. The altitude to the hypotenuse (7.2 cm) is a different length.","difficulty":"very-hard","questionHi":"9 cm और 12 cm भुजाओं वाले एक समकोण त्रिभुज में समकोण के समद्विभाजक की लंबाई, कर्ण तक मापने पर, क्या है?","optionsHi":["7.2 cm","36/7 cm","6 cm","36√2/7 cm"],"explanationHi":"क्षेत्रफल बाँटने पर: ½ × 9 × 12 = ½ × 9 × d sin45° + ½ × 12 × d sin45°, अतः 54 = (21/2)(d/√2) और d = 36√2/7 ≈ 7.27 cm। कर्ण पर लंब (7.2 cm) एक भिन्न लंबाई है।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-199","question":"The diagonals of a quadrilateral are 20 cm and 12 cm and they intersect at an angle of 30°. What is the area of the quadrilateral?","options":["120 cm²","60√3 cm²","60 cm²","30 cm²"],"answer":2,"explanation":"Area = ½ × d₁ × d₂ × sin θ = ½ × 20 × 12 × ½ = 60 cm². The value 120 drops the ½ and the sine factor is mishandled in 60√3.","difficulty":"hard","questionHi":"एक चतुर्भुज के विकर्ण 20 cm और 12 cm हैं और वे 30° के कोण पर प्रतिच्छेद करते हैं। चतुर्भुज का क्षेत्रफल क्या है?","optionsHi":["120 cm²","60√3 cm²","60 cm²","30 cm²"],"explanationHi":"क्षेत्रफल = ½ × d₁ × d₂ × sin θ = ½ × 20 × 12 × ½ = 60 cm²। 120 में ½ छूट गया है और 60√3 में sin का मान गलत लिया गया है।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-200","question":"In a convex quadrilateral ABCD, AB = 15 cm, BC = 20 cm, CD = 24 cm, DA = 7 cm and ∠ABC = 90°. What is its area?","options":["234 cm²","258 cm²","300 cm²","210 cm²"],"answer":0,"explanation":"AC = √(15² + 20²) = 25. Then 7² + 24² = 625 = 25², so triangle ACD is right-angled at D. Area = ½ × 15 × 20 + ½ × 7 × 24 = 150 + 84 = 234 cm².","difficulty":"hard","questionHi":"एक उत्तल चतुर्भुज ABCD में AB = 15 cm, BC = 20 cm, CD = 24 cm, DA = 7 cm और ∠ABC = 90° है। उसका क्षेत्रफल क्या है?","optionsHi":["234 cm²","258 cm²","300 cm²","210 cm²"],"explanationHi":"AC = √(15² + 20²) = 25। फिर 7² + 24² = 625 = 25², अतः त्रिभुज ACD, D पर समकोण है। क्षेत्रफल = ½ × 15 × 20 + ½ × 7 × 24 = 150 + 84 = 234 cm²।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-201","question":"A regular hexagon and an equilateral triangle are both inscribed in the same circle. What is the ratio of the area of the hexagon to the area of the triangle?","options":["3 : 2","4 : 3","3 : 1","2 : 1"],"answer":3,"explanation":"With circle radius r, the hexagon has side r and area 6 × (√3/4)r² = (3√3/2)r². The triangle has side r√3 and area (3√3/4)r². The ratio is 2 : 1.","difficulty":"hard","questionHi":"एक समषट्भुज और एक समबाहु त्रिभुज दोनों एक ही वृत्त में अंतःस्थापित हैं। समषट्भुज के क्षेत्रफल और त्रिभुज के क्षेत्रफल का अनुपात क्या है?","optionsHi":["3 : 2","4 : 3","3 : 1","2 : 1"],"explanationHi":"वृत्त की त्रिज्या r होने पर समषट्भुज की भुजा r और क्षेत्रफल 6 × (√3/4)r² = (3√3/2)r² है। त्रिभुज की भुजा r√3 और क्षेत्रफल (3√3/4)r² है। अनुपात 2 : 1।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-202","question":"Two circles of radii 9 cm and 4 cm touch each other externally. What is the length of a direct common tangent to them?","options":["13 cm","12 cm","5 cm","6 cm"],"answer":1,"explanation":"The tangent length is √(d² − (R − r)²) with d = R + r, which simplifies to 2√(Rr) = 2√36 = 12 cm.","difficulty":"hard","questionHi":"9 cm और 4 cm त्रिज्या वाले दो वृत्त एक-दूसरे को बाह्य रूप से स्पर्श करते हैं। उनकी एक सरल उभयनिष्ठ स्पर्श रेखा की लंबाई क्या है?","optionsHi":["13 cm","12 cm","5 cm","6 cm"],"explanationHi":"स्पर्श रेखा की लंबाई √(d² − (R − r)²) है, जहाँ d = R + r, जो 2√(Rr) = 2√36 = 12 cm हो जाती है।","subtopic":"circles-sectors","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-203","question":"A triangle with sides 6 cm, 8 cm and 10 cm has both a circumscribed circle and an inscribed circle. What is the difference between their areas? (π = 22/7)","options":["54.57 cm²","66 cm²","78.57 cm²","44 cm²"],"answer":1,"explanation":"It is a right triangle, so R = hypotenuse/2 = 5 and r = (6 + 8 − 10)/2 = 2. Difference = π(25 − 4) = 21 × 22/7 = 66 cm².","difficulty":"hard","questionHi":"6 cm, 8 cm और 10 cm भुजाओं वाले त्रिभुज का एक परिवृत्त और एक अंतःवृत्त है। उनके क्षेत्रफलों का अंतर क्या है? (π = 22/7)","optionsHi":["54.57 cm²","66 cm²","78.57 cm²","44 cm²"],"explanationHi":"यह समकोण त्रिभुज है, अतः R = कर्ण/2 = 5 और r = (6 + 8 − 10)/2 = 2। अंतर = π(25 − 4) = 21 × 22/7 = 66 cm²।","subtopic":"circles-sectors","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-204","question":"A circle touches all four sides of a rhombus whose diagonals are 24 cm and 32 cm. What is the radius of the circle?","options":["9 cm","19.2 cm","10.4 cm","9.6 cm"],"answer":3,"explanation":"Side = √(12² + 16²) = 20 and area = ½ × 24 × 32 = 384. The distance between opposite sides is 384/20 = 19.2, which is the diameter, so the radius is 9.6 cm.","difficulty":"very-hard","questionHi":"एक वृत्त एक समचतुर्भुज की चारों भुजाओं को स्पर्श करता है, जिसके विकर्ण 24 cm और 32 cm हैं। वृत्त की त्रिज्या क्या है?","optionsHi":["9 cm","19.2 cm","10.4 cm","9.6 cm"],"explanationHi":"भुजा = √(12² + 16²) = 20 और क्षेत्रफल = ½ × 24 × 32 = 384। आमने-सामने की भुजाओं के बीच की दूरी 384/20 = 19.2 है, जो व्यास है, अतः त्रिज्या 9.6 cm।","subtopic":"triangles-quadrilaterals","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-205","question":"A cube of side 14 cm has the largest possible hemispherical hollow scooped out of the centre of its top face. What is the total surface area of the remaining solid? (π = 22/7)","options":["1,330 cm²","1,176 cm²","1,022 cm²","1,484 cm²"],"answer":0,"explanation":"The hemisphere has radius 7. Surface = 6 × 196 − πr² (removed circle, 154) + 2πr² (curved hollow, 308) = 1176 − 154 + 308 = 1,330 cm².","difficulty":"very-hard","questionHi":"14 cm भुजा वाले एक घन के ऊपरी फलक के केंद्र से सबसे बड़ा संभव अर्धगोलाकार गड्ढा खोद लिया जाता है। शेष ठोस का कुल पृष्ठीय क्षेत्रफल क्या है? (π = 22/7)","optionsHi":["1,330 cm²","1,176 cm²","1,022 cm²","1,484 cm²"],"explanationHi":"अर्धगोले की त्रिज्या 7 है। पृष्ठीय क्षेत्रफल = 6 × 196 − πr² (हटाया गया वृत्त, 154) + 2πr² (वक्र गड्ढा, 308) = 1176 − 154 + 308 = 1,330 cm²।","subtopic":"frustum-composite","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-206","question":"A solid cylinder of radius 7 cm and height 20 cm has a cone of the same base and the same height hollowed out of it. What is the volume of the remaining solid? (π = 22/7)","options":["3,080 cm³","1,026.67 cm³","2,053.33 cm³","1,540 cm³"],"answer":2,"explanation":"Remaining volume = cylinder − cone = (1 − ⅓)πr²h = ⅔ × 22/7 × 49 × 20 = 6160/3 ≈ 2,053.33 cm³.","difficulty":"hard","questionHi":"7 cm त्रिज्या और 20 cm ऊँचाई वाले एक ठोस बेलन में से उसी आधार और उसी ऊँचाई वाला एक शंकु खोखला कर निकाल लिया जाता है। शेष ठोस का आयतन क्या है? (π = 22/7)","optionsHi":["3,080 cm³","1,026.67 cm³","2,053.33 cm³","1,540 cm³"],"explanationHi":"शेष आयतन = बेलन − शंकु = (1 − ⅓)πr²h = ⅔ × 22/7 × 49 × 20 = 6160/3 ≈ 2,053.33 cm³।","subtopic":"frustum-composite","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-207","question":"What is the length of the longest straight rod that can be placed inside a cuboidal room 12 m long, 9 m wide and 8 m high?","options":["15 m","13 m","29 m","17 m"],"answer":3,"explanation":"The longest rod lies along the space diagonal: √(12² + 9² + 8²) = √289 = 17 m.","difficulty":"moderate","questionHi":"12 m लंबे, 9 m चौड़े और 8 m ऊँचे घनाभाकार कमरे में रखी जा सकने वाली सबसे लंबी सीधी छड़ की लंबाई क्या है?","optionsHi":["15 m","13 m","29 m","17 m"],"explanationHi":"सबसे लंबी छड़ अंतःकर्ण के अनुदिश रखी जाती है: √(12² + 9² + 8²) = √289 = 17 m।","subtopic":"cube-cuboid","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-208","question":"A hemispherical bowl of internal radius 10 cm is full of milk, which is poured into a cylindrical vessel of base radius 5 cm. What is the height of the milk in the cylinder?","options":["40 cm","26.67 cm","20 cm","53.33 cm"],"answer":1,"explanation":"Hemisphere volume = ⅔π × 1000. Dividing by the cylinder base 25π gives (2000/3)/25 = 80/3 = 26.67 cm. Using the full-sphere volume would give 53.33 cm.","difficulty":"hard","questionHi":"10 cm आंतरिक त्रिज्या वाला एक अर्धगोलाकार कटोरा दूध से भरा है, जिसे 5 cm आधार त्रिज्या वाले बेलनाकार बर्तन में उँडेला जाता है। बेलन में दूध की ऊँचाई क्या है?","optionsHi":["40 cm","26.67 cm","20 cm","53.33 cm"],"explanationHi":"अर्धगोले का आयतन = ⅔π × 1000। बेलन के आधार 25π से भाग देने पर (2000/3)/25 = 80/3 = 26.67 cm। पूरे गोले का आयतन लेने पर 53.33 cm आता।","subtopic":"melting-recasting","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-mensuration-209","question":"Water flows through a pipe of internal diameter 14 cm at 5 m/s into a rectangular tank 12 m long, 11 m wide and 7 m deep. How long does it take to fill the empty tank? (π = 22/7)","options":["2 hours 40 minutes","1 hour 40 minutes","3 hours 20 minutes","6 hours 40 minutes"],"answer":2,"explanation":"Flow per second = π × 7² × 500 cm³ = 77,000 cm³. Tank volume = 924 m³ = 9.24 × 10⁸ cm³. Time = 9.24 × 10⁸/77,000 = 12,000 s = 3 h 20 min.","difficulty":"very-hard","questionHi":"आंतरिक व्यास 14 cm वाले एक पाइप से पानी 5 m/s की चाल से 12 m लंबे, 11 m चौड़े और 7 m गहरे आयताकार टैंक में बहता है। खाली टैंक को भरने में कितना समय लगेगा? (π = 22/7)","optionsHi":["2 घंटे 40 मिनट","1 घंटा 40 मिनट","3 घंटे 20 मिनट","6 घंटे 40 मिनट"],"explanationHi":"प्रति सेकंड प्रवाह = π × 7² × 500 cm³ = 77,000 cm³। टैंक का आयतन = 924 m³ = 9.24 × 10⁸ cm³। समय = 9.24 × 10⁸/77,000 = 12,000 s = 3 घंटे 20 मिनट।","subtopic":"melting-recasting","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

